const K_BROADCAST_MSG = () => localStorage.getItem(K_BROADCAST) || '';
function saveBroadcastMessage() {
  const msg = (document.getElementById('broadcastMsgInput').value||'').trim();
  localStorage.setItem(K_BROADCAST, msg);
  const status = document.getElementById('broadcastStatus');
  if (status) { status.innerHTML = msg ? '<i class="fa-solid fa-circle-check"></i> Message published to all schools.' : '<i class="fa-solid fa-circle-check"></i> Banner cleared.'; setTimeout(()=>{status.innerHTML='';},3000); }
  renderBroadcastPreview();
  showToast(msg ? '<i class="fa-solid fa-bullhorn"></i> Broadcast message published!' : 'Broadcast cleared','success');
}
function clearBroadcastMessage() {
  localStorage.removeItem(K_BROADCAST);
  const inp = document.getElementById('broadcastMsgInput'); if(inp) inp.value='';
  renderBroadcastPreview();
  showToast('Broadcast cleared','info');
}
function renderBroadcastPreview() {
  const msg = localStorage.getItem(K_BROADCAST)||'';
  const prev = document.getElementById('broadcastPreview');
  const prevTxt = document.getElementById('broadcastPreviewText');
  if (!prev) return;
  if (msg) { prev.style.display=''; prevTxt.textContent=msg; } else { prev.style.display='none'; }
}
function loadBroadcastBanner() {
  // Called on school login — show banner if message set
  const msg = localStorage.getItem(K_BROADCAST)||'';
  const banner = document.getElementById('platformBroadcastBanner');
  const bannerTxt = document.getElementById('platformBroadcastText');
  if (!banner) return;
  if (msg) { banner.style.display='flex'; if(bannerTxt) bannerTxt.textContent=msg; }
  else { banner.style.display='none'; }
}

// ══ Platform Admin — collapsible cards ══
function initPlatformCollapse() {
  const platform = document.getElementById('s-platform');
  if (!platform) return;

  // 1. Init collapsible cards
  platform.querySelectorAll('.card').forEach(card => {
    // Skip if already initialized
    if (card.querySelector('.plat-card-header')) return;
    const h3 = card.querySelector(':scope > h3, :scope > .card-header h3');
    if (!h3) return;

    // Determine a storage key from h3 text
    const keySlug = 'plat_collapse_' + h3.textContent.trim().replace(/[^a-z0-9]/gi,'_').slice(0,40);

    // Wrap h3 + create header row
    const header = document.createElement('div');
    header.className = 'plat-card-header';

    const btn = document.createElement('button');
    btn.className = 'plat-collapse-btn';
    btn.title = 'Collapse / Expand section';
    btn.textContent = '▾';
    btn.type = 'button';

    h3.parentNode.insertBefore(header, h3);
    header.appendChild(h3);
    header.appendChild(btn);

    // Wrap remaining card content in a body div
    const body = document.createElement('div');
    body.className = 'plat-card-body';
    while (card.children.length > 1) {
      body.appendChild(card.children[1]);
    }
    card.appendChild(body);

    // Restore saved state
    const isCollapsed = localStorage.getItem(keySlug) === '1';
    if (isCollapsed) {
      body.classList.add('collapsed');
      btn.classList.add('collapsed');
    }

    // Toggle handler
    const toggle = () => {
      const nowCollapsed = body.classList.toggle('collapsed');
      btn.classList.toggle('collapsed', nowCollapsed);
      localStorage.setItem(keySlug, nowCollapsed ? '1' : '0');
    };
    header.addEventListener('click', toggle);
  });

  // 2. Add "Collapse All / Expand All" toolbar to each visible tab panel
  platform.querySelectorAll('.plat-tab-panel').forEach(panel => {
    if (panel.querySelector('.plat-collapse-toolbar')) return; // already added
    const cards = panel.querySelectorAll('.card');
    if (cards.length < 2) return; // toolbar only useful when 2+ cards

    const toolbar = document.createElement('div');
    toolbar.className = 'plat-collapse-toolbar';

    const collapseAllBtn = document.createElement('button');
    collapseAllBtn.className = 'plat-collapse-all-btn';
    collapseAllBtn.type = 'button';
    collapseAllBtn.innerHTML = '⊖ Collapse All';
    collapseAllBtn.title = 'Collapse all sections in this tab';
    collapseAllBtn.addEventListener('click', () => {
      panel.querySelectorAll('.plat-card-body').forEach(body => {
        body.classList.add('collapsed');
        const btn = body.closest('.card').querySelector('.plat-collapse-btn');
        if (btn) btn.classList.add('collapsed');
        const h3 = body.closest('.card').querySelector('.plat-card-header h3');
        if (h3) {
          const keySlug = 'plat_collapse_' + h3.textContent.trim().replace(/[^a-z0-9]/gi,'_').slice(0,40);
          localStorage.setItem(keySlug, '1');
        }
      });
    });

    const expandAllBtn = document.createElement('button');
    expandAllBtn.className = 'plat-collapse-all-btn';
    expandAllBtn.type = 'button';
    expandAllBtn.innerHTML = '⊕ Expand All';
    expandAllBtn.title = 'Expand all sections in this tab';
    expandAllBtn.addEventListener('click', () => {
      panel.querySelectorAll('.plat-card-body').forEach(body => {
        body.classList.remove('collapsed');
        const btn = body.closest('.card').querySelector('.plat-collapse-btn');
        if (btn) btn.classList.remove('collapsed');
        const h3 = body.closest('.card').querySelector('.plat-card-header h3');
        if (h3) {
          const keySlug = 'plat_collapse_' + h3.textContent.trim().replace(/[^a-z0-9]/gi,'_').slice(0,40);
          localStorage.setItem(keySlug, '0');
        }
      });
    });

    toolbar.appendChild(collapseAllBtn);
    toolbar.appendChild(expandAllBtn);
    panel.insertBefore(toolbar, panel.firstChild);
  });
}

