// Returns { core:[], elective:[] } for a given pathway id
function getCBCSubjectsForPathway(pwId) {
  const universal = CBC_SUBJECTS.universal_core;
  const pw = CBC_SUBJECTS[pwId];
  if (!pw) return { core: universal, elective: [] };
  return {
    core:     [...universal, ...(pw.core || [])],
    elective: pw.elective || []
  };
}

// Seed CBC subjects from catalogue for a given pathway
// Returns array of subject objects that were newly created (not pushing to global yet)
function seedCBCSubjectsForPathway(pwId) {
  const { core, elective } = getCBCSubjectsForPathway(pwId);
  const all = [...core, ...elective];
  const added = [];
  all.forEach(s => {
    if (!subjects.find(x => x.code === s.code)) {
      const newSub = { id: uid(), name: s.name, code: s.code, max: 100,
        category: s.cat, teacherId: '', studentIds: [],
        pathway: pwId, cbcCore: core.some(c => c.code === s.code),
        examinable: defaultExaminableForCode(s.code) };
      subjects.push(newSub);
      added.push(newSub);
    }
  });
  if (added.length) {
    save(K.subjects, subjects);
    populateAllDropdowns();
    renderSubjects();
  }
  return added;
}

// Auto-enrol a student in core subjects for their pathway
function autoEnrolCoreSubjects(stu) {
  if (!isSeniorSchool() || !stu.pathway) return;
  const { core } = getCBCSubjectsForPathway(stu.pathway);
  core.forEach(c => {
    const sub = subjects.find(x => x.code === c.code);
    if (sub) {
      if (!sub.studentIds) sub.studentIds = [];
      if (!sub.studentIds.includes(stu.id)) sub.studentIds.push(stu.id);
      if (!stu.subjectIds) stu.subjectIds = [];
      if (!stu.subjectIds.includes(sub.id)) stu.subjectIds.push(sub.id);
    }
  });
}

// Show the senior subject seeding panel
function showSeniorSubjectPanel() {
  const existing = subjects.map(s => s.code);
  const pwCards = getOfferedPathways().map(pw => {
    const { core, elective } = getCBCSubjectsForPathway(pw.id);
    const newCore = core.filter(s => !existing.includes(s.code));
    const newElec = elective.filter(s => !existing.includes(s.code));
    const total = newCore.length + newElec.length;
    return `<div style="border:1.5px solid ${pw.color}40;border-radius:10px;padding:.85rem 1rem;background:${pw.color}08;flex:1;min-width:220px">
      <div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.5rem">
        <span style="width:28px;height:28px;border-radius:50%;background:${pw.color}20;display:flex;align-items:center;justify-content:center">
          <i class="fa-solid ${pw.icon}" style="color:${pw.color};font-size:.8rem"></i>
        </span>
        <strong style="font-size:.88rem">${pw.label}</strong>
      </div>
      <div style="font-size:.75rem;color:var(--muted);margin-bottom:.65rem">
        ${core.length} core · ${elective.length} elective
        ${total > 0 ? `<span style="color:#f59e0b;font-weight:600"> (${total} new)</span>` : '<span style="color:#10b981;font-weight:600"> ✓ all seeded</span>'}
      </div>
      <div style="font-size:.7rem;color:var(--muted);margin-bottom:.5rem;line-height:1.5">
        <strong>Core:</strong> ${core.map(s=>`<span style="background:${pw.color}15;border-radius:4px;padding:.05rem .35rem;margin:.1rem;display:inline-block">${s.name}</span>`).join('')}
      </div>
      ${total > 0 ? `<button onclick="seedCBCSubjectsForPathway('${pw.id}');closeModal();showToast('${pw.label} subjects seeded','success')" 
        class="btn btn-sm" style="background:${pw.color};color:#fff;border:none;width:100%;margin-top:.3rem;font-size:.78rem">
        <i class="fa-solid fa-wand-magic-sparkles"></i> Seed ${pw.label} Subjects</button>` 
      : ''}
    </div>`;
  }).join('');

  showModal('<i class="fa-solid fa-wand-magic-sparkles"></i> Seed CBC Senior School Subjects',
    `<p style="font-size:.82rem;color:var(--muted);margin-bottom:1rem">
      Automatically add all official CBC Grade 10 subjects for each pathway. Core subjects will be flagged and auto-assigned to students of that pathway.
    </p>
    <div style="display:flex;gap:.75rem;flex-wrap:wrap;margin-bottom:1rem">${pwCards}</div>
    <button onclick="getOfferedPathways().forEach(pw=>seedCBCSubjectsForPathway(pw.id));closeModal();showToast('All CBC subjects seeded','success')"
      class="btn btn-primary btn-sm" style="width:100%"><i class="fa-solid fa-layer-group"></i> Seed ALL Pathways at Once</button>`,
    [{ label:'Close', cls:'btn-outline', action:'closeModal()' }]
  );
}
function getPathway(id) { return PATHWAYS.find(p=>p.id===id) || null; }

// ── CBC Rationalised Primary School Subject Catalogue ─────────────
// Source: KICD / Ministry of Education — learning-area rationalisation circular
// (Dec 2023, effective Term 1 2024): Lower Primary (Grade 1-3) capped at 7 learning
// areas, Upper Primary (Grade 4-6) capped at 8.
const PRIMARY_SUBJECTS = {
  lower: [ // Grade 1 – 3 (7 learning areas)
    { name:'Indigenous Language Activities', code:'ILA', cat:'Languages' },
    { name:'Kiswahili Language Activities',  code:'KIS', cat:'Languages' },
    { name:'English Language Activities',    code:'ENG', cat:'Languages' },
    { name:'Mathematical Activities',        code:'MAT', cat:'Core' },
    { name:'Religious Education Activities', code:'REA', cat:'Core' },
    { name:'Environmental Activities',       code:'ENV', cat:'Core' },     // incl. Hygiene & Nutrition
    { name:'Creative Activities',            code:'CRA', cat:'Elective' },
  ],
  upper: [ // Grade 4 – 6 (8 learning areas)
    { name:'English',                   code:'ENG', cat:'Languages' },
    { name:'Kiswahili',                 code:'KIS', cat:'Languages' },
    { name:'Mathematics',               code:'MTH', cat:'Core' },
    { name:'Religious Education',       code:'REL', cat:'Core' },
    { name:'Agriculture and Nutrition', code:'AGN', cat:'Technical' },     // merged Agriculture + Home Science
    { name:'Social Studies',            code:'SST', cat:'Core' },
    { name:'Creative Arts',             code:'CRA', cat:'Elective' },      // merged Art & Craft + Music + PHE
    { name:'Science and Technology',    code:'SCT', cat:'Core' },
  ],
};
const PRIMARY_BANDS = [
  { id:'lower', label:'Lower Primary (Grade 1–3)', color:'#0ea5e9', icon:'fa-seedling' },
  { id:'upper', label:'Upper Primary (Grade 4–6)',  color:'#7c3aed', icon:'fa-graduation-cap' },
];
function getPrimarySubjectsForBand(band) { return PRIMARY_SUBJECTS[band] || []; }

// Seed the rationalised subject set for a primary band. Returns newly-created subjects.
function seedPrimarySubjectsForBand(band) {
  const list = getPrimarySubjectsForBand(band);
  const added = [];
  list.forEach(s => {
    if (!subjects.find(x => x.code === s.code && x.primaryBand === band)) {
      const newSub = { id: uid(), name: s.name, code: s.code, max: 100,
        category: s.cat, teacherId: '', studentIds: [],
        primaryBand: band, examinable: true };
      subjects.push(newSub);
      added.push(newSub);
    }
  });
  if (added.length) {
    save(K.subjects, subjects);
    populateAllDropdowns();
    renderSubjects();
    autoEnrolPrimarySubjectsForBand(band);
  }
  return added;
}

// Enrol every current student whose class falls in the given band into that band's subjects.
function autoEnrolPrimarySubjectsForBand(band) {
  if (!isPrimarySchool()) return;
  const bandSubs = subjects.filter(s => s.primaryBand === band);
  if (!bandSubs.length) return;
  let changed = false;
  students.forEach(stu => {
    const cls = classes.find(c => c.id === stu.classId);
    if (!cls || getPrimaryBandForClass(cls) !== band) return;
    bandSubs.forEach(sub => {
      if (!sub.studentIds) sub.studentIds = [];
      if (!sub.studentIds.includes(stu.id)) { sub.studentIds.push(stu.id); changed = true; }
      if (!stu.subjectIds) stu.subjectIds = [];
      if (!stu.subjectIds.includes(sub.id)) { stu.subjectIds.push(sub.id); changed = true; }
    });
  });
  if (changed) { save(K.subjects, subjects); saveStudents(); }
}

// Auto-enrol a single newly-added primary student into their band's subjects.
// Mirrors autoEnrolCoreSubjects() for Senior School; called from the same save flow.
function autoEnrolPrimaryStudent(stu) {
  if (!isPrimarySchool() || !stu) return;
  const cls  = classes.find(c => c.id === stu.classId);
  const band = getPrimaryBandForClass(cls);
  if (!band) return;
  subjects.filter(s => s.primaryBand === band).forEach(sub => {
    if (!sub.studentIds) sub.studentIds = [];
    if (!sub.studentIds.includes(stu.id)) sub.studentIds.push(stu.id);
    if (!stu.subjectIds) stu.subjectIds = [];
    if (!stu.subjectIds.includes(sub.id)) stu.subjectIds.push(sub.id);
  });
}

// Show the primary subject seeding panel (mirrors showSeniorSubjectPanel)
function showPrimarySubjectPanel() {
  const existing = subjects.filter(s => s.primaryBand).map(s => s.primaryBand + ':' + s.code);
  const cards = PRIMARY_BANDS.map(b => {
    const list = getPrimarySubjectsForBand(b.id);
    const newCount = list.filter(s => !existing.includes(b.id + ':' + s.code)).length;
    return `<div style="border:1.5px solid ${b.color}40;border-radius:10px;padding:.85rem 1rem;background:${b.color}08;flex:1;min-width:240px">
      <div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.5rem">
        <span style="width:28px;height:28px;border-radius:50%;background:${b.color}20;display:flex;align-items:center;justify-content:center">
          <i class="fa-solid ${b.icon}" style="color:${b.color};font-size:.8rem"></i>
        </span>
        <strong style="font-size:.88rem">${b.label}</strong>
      </div>
      <div style="font-size:.75rem;color:var(--muted);margin-bottom:.65rem">
        ${list.length} learning areas
        ${newCount > 0 ? `<span style="color:#f59e0b;font-weight:600"> (${newCount} new)</span>` : '<span style="color:#10b981;font-weight:600"> ✓ all seeded</span>'}
      </div>
      <div style="font-size:.7rem;color:var(--muted);margin-bottom:.5rem;line-height:1.5">
        ${list.map(s=>`<span style="background:${b.color}15;border-radius:4px;padding:.05rem .35rem;margin:.1rem;display:inline-block">${s.name}</span>`).join('')}
      </div>
      ${newCount > 0 ? `<button onclick="seedPrimarySubjectsForBand('${b.id}');closeModal();showToast('${b.label} subjects seeded','success')"
        class="btn btn-sm" style="background:${b.color};color:#fff;border:none;width:100%;margin-top:.3rem;font-size:.78rem">
        <i class="fa-solid fa-wand-magic-sparkles"></i> Seed ${b.label} Subjects</button>`
      : ''}
    </div>`;
  }).join('');

  showModal('<i class="fa-solid fa-wand-magic-sparkles"></i> Seed Primary School Subjects',
    `<p style="font-size:.82rem;color:var(--muted);margin-bottom:1rem">
      Automatically add the rationalised CBC learning areas (2024 KICD review) for Lower and Upper Primary. Students already placed in a matching class/grade are enrolled automatically.
    </p>
    <div style="display:flex;gap:.75rem;flex-wrap:wrap;margin-bottom:1rem">${cards}</div>
    <button onclick="['lower','upper'].forEach(b=>seedPrimarySubjectsForBand(b));closeModal();showToast('All primary subjects seeded','success')"
      class="btn btn-primary btn-sm" style="width:100%"><i class="fa-solid fa-layer-group"></i> Seed BOTH Bands at Once</button>`,
    [{ label:'Close', cls:'btn-outline', action:'closeModal()' }]
  );
}

function applySchoolLevelUI() {
  const senior  = isSeniorSchool();
  const primary = isPrimarySchool();
  // Show/hide Pathway column in student table header (re-rendered by renderStudents)
  renderStudents();
  // Show/hide pathway + track filter
  const pf = document.getElementById('stuPathwayFilterWrap');
  if (pf) pf.style.display = senior ? '' : 'none';
  const tf = document.getElementById('stuTrackFilterWrap');
  if (tf) tf.style.display = 'none'; // reset; shown when pathway is selected
  // Show/hide pathway + track fields in add-student form
  const pfw = document.getElementById('stuPathwayWrap');
  if (pfw) pfw.style.display = senior ? '' : 'none';
  const tfw = document.getElementById('stuTrackWrap');
  if (tfw) tfw.style.display = 'none'; // reset; updateStuTrackDropdown handles showing it
  const cfw = document.getElementById('stuSubjectCombWrap');
  if (cfw) cfw.style.display = 'none';
  // Show/hide pathway fields in subjects form
  const spw = document.getElementById('subPathwayWrap');
  if (spw) spw.style.display = senior ? '' : 'none';
  // Show/hide seed button
  const ssb = document.getElementById('seniorSubjectSeedBtn');
  if (ssb) ssb.style.display = senior ? '' : 'none';
  const psb = document.getElementById('primarySubjectSeedBtn');
  if (psb) psb.style.display = primary ? '' : 'none';
  // Which pathways this school offers (Single / Double / Triple Pathway)
  try { renderPathwaysOfferedUI(); } catch(e) {}
  refreshPathwayDropdowns();
}

function saveGlobalTeacherRestrictions() {
  settings.restrictTeacherAnalytics = !!document.getElementById('restrictTeacherAnalytics')?.checked;
  settings.restrictTeacherFees      = !!document.getElementById('restrictTeacherFees')?.checked;
  settings.restrictTeacherList      = !!document.getElementById('restrictTeacherList')?.checked;
  settings.restrictTeacherSettings  = !!document.getElementById('restrictTeacherSettings')?.checked;
  save(K.settings, [settings]);
  // Re-apply UI if a teacher is currently logged in
  if (currentUser && currentUser.role === 'teacher') applyRoleBasedUI();
  showToast('Teacher restrictions saved <i class="fa-solid fa-check"></i>', 'success');
}

// ═══════════════ OVERALL GRADE THRESHOLDS ═══════════════

function renderOverallGradingCard() {
  const card = document.getElementById('overallGradingCard');
  if (!card) return;
  const mode = settings.overallGradingMode || 'auto';
  const gs   = getActiveGradingSystem();

  // Toggle the mode radio buttons
  const autoRad   = document.getElementById('ogModeAuto');
  const customRad = document.getElementById('ogModeCustom');
  if (autoRad)   autoRad.checked   = (mode === 'auto');
  if (customRad) customRad.checked = (mode === 'custom');

  // Build the preview / edit table
  renderOverallGradingTable(mode, gs);
}

function renderOverallGradingTable(mode, gs) {
  const wrap = document.getElementById('ogTableWrap');
  if (!wrap) return;
  gs = gs || getActiveGradingSystem();
  mode = mode || (settings.overallGradingMode || 'auto');

  const subjectMax = gs.bands.reduce((max, b) => Math.max(max, b.max), 100); // use 100 as base
  const autoThresh = computeAutoThresholds(gs, 100);

  if (mode === 'auto') {
    // Show read-only preview of auto-computed thresholds
    const rows = autoThresh.map(t => `
      <tr>
        <td><span class="badge ${t.cls}">${t.grade}</span></td>
        <td>${t.label}</td>
        <td style="text-align:center;font-weight:700;color:var(--primary)">&ge; ${(t.minMean).toFixed(1)}</td>
        <td style="text-align:center;color:var(--muted)">&le; ${(t.maxMean).toFixed(1)}</td>
      </tr>`).join('');
    wrap.innerHTML = `
      <p style="font-size:.82rem;color:var(--muted);margin-bottom:.75rem">
        Thresholds are automatically calculated by dividing <strong>100</strong> (subject max) evenly across all
        <strong>${gs.bands.length}</strong> grade bands in the active grading system
        (<em>${gs.name}</em>). Switch to <strong>Custom</strong> to set your own values.
      </p>
      <div class="tbl-wrap">
        <table style="font-size:.85rem">
          <thead><tr><th>Grade</th><th>Label</th><th>Min Mean</th><th>Max Mean</th></tr></thead>
          <tbody>${rows}</tbody>
        </table>
      </div>`;
  } else {
    // Custom mode — editable rows, pre-filled from saved thresholds or auto-computed defaults
    const saved = Array.isArray(settings.overallGradeThresholds) && settings.overallGradeThresholds.length
      ? settings.overallGradeThresholds
      : autoThresh;
    const rows = saved.map((t,i) => `
      <tr class="og-row" data-idx="${i}">
        <td><span class="badge ${t.cls}">${t.grade}</span></td>
        <td style="color:var(--muted);font-size:.8rem">${t.label}</td>
        <td style="text-align:center">
          <input type="number" class="og-min" value="${t.minMean}" min="0" max="100" step="0.5"
            style="width:70px;padding:.3rem .4rem;border:1px solid var(--border);border-radius:5px;
                   background:var(--surface);color:var(--text);font-family:var(--font);font-size:.82rem;text-align:center"/>
        </td>
        <td style="text-align:center;color:var(--muted);font-size:.8rem">${(t.maxMean||100).toFixed(1)}</td>
      </tr>`).join('');
    wrap.innerHTML = `
      <p style="font-size:.82rem;color:var(--muted);margin-bottom:.75rem">
        Set the minimum mean score required to achieve each grade. Values are in the same unit as subject marks
        (e.g. if subjects are out of 100, enter the mean mark out of 100).
        The system will award the <em>highest</em> grade whose minimum threshold the student meets.
      </p>
      <div class="tbl-wrap" style="margin-bottom:.75rem">
        <table style="font-size:.85rem">
          <thead><tr><th>Grade</th><th>Label</th><th>Min Mean Score</th><th>Max Mean (auto)</th></tr></thead>
          <tbody id="ogRows">${rows}</tbody>
        </table>
      </div>
      <div style="display:flex;gap:.75rem;flex-wrap:wrap;align-items:center">
        <button class="btn btn-outline btn-sm" onclick="ogResetToAuto()">↺ Reset to Auto Defaults</button>
        <button class="btn btn-primary btn-sm" onclick="saveOverallGradeThresholds()"><i class="fa-solid fa-floppy-disk"></i> Save Thresholds</button>
      </div>`;
  }
}

function onOgModeChange(mode) {
  settings.overallGradingMode = mode;
  save(K.settings, [settings]);
  renderOverallGradingTable(mode);
  showToast(mode === 'auto' ? 'Auto grading mode active <i class="fa-solid fa-check"></i>' : 'Custom mode — set your thresholds below', 'success');
}

function ogResetToAuto() {
  const gs = getActiveGradingSystem();
  const autoThresh = computeAutoThresholds(gs, 100);
  settings.overallGradeThresholds = autoThresh;
  save(K.settings, [settings]);
  renderOverallGradingTable('custom');
  showToast('Thresholds reset to auto-computed values <i class="fa-solid fa-check"></i>', 'info');
}

function saveOverallGradeThresholds() {
  const rows = document.querySelectorAll('#ogRows .og-row');
  if (!rows.length) { showToast('No thresholds to save','error'); return; }
  const gs = getActiveGradingSystem();
  const bandsSorted = [...gs.bands].sort((a,b) => b.min - a.min);
  const clsMap = { EE1:'b-green',EE2:'b-teal',ME1:'b-blue',ME2:'b-lblue',AE1:'b-amber',AE2:'b-orange',BE1:'b-red',BE2:'b-dkred' };
  const thresholds = [];
  let valid = true;
  rows.forEach((row, i) => {
    const minInput = row.querySelector('.og-min');
    const minMean  = parseFloat(minInput?.value);
    if (isNaN(minMean) || minMean < 0) { valid = false; return; }
    const band = bandsSorted[i] || {};
    thresholds.push({
      grade:   band.grade || row.dataset.grade || '?',
      label:   band.label || '',
      cls:     clsMap[band.grade] || band.cls || 'b-blue',
      minMean: minMean,
      maxMean: i === 0 ? 100 : parseFloat((thresholds[i-1]?.minMean - 0.01).toFixed(2))
    });
  });
  if (!valid) { showToast('Please fill all minimum values correctly','error'); return; }
  // Sort descending by minMean and fix maxMean chain
  thresholds.sort((a,b) => b.minMean - a.minMean);
  thresholds.forEach((t,i) => { t.maxMean = i===0 ? 100 : parseFloat((thresholds[i-1].minMean - 0.01).toFixed(2)); });
  settings.overallGradeThresholds = thresholds;
  save(K.settings, [settings]);
  renderOverallGradingTable('custom');
  showToast('Overall grade thresholds saved <i class="fa-solid fa-check"></i>', 'success');
}


function renderAdminList() {
  const list=[
    {name:'Super Admin',username:'superadmin',role:'superadmin',builtin:true},
    ...admins
  ];
  document.getElementById('adminList').innerHTML=list.map(a=>`
    <div class="admin-item">
      <div><div class="ai-name">${a.name}</div><div class="ai-role">${a.username} · <span class="badge ${a.role==='superadmin'?'b-amber':a.role==='principal'?'b-teal':a.role==='bursar'?'b-green':'b-blue'}">${a.role}</span></div></div>
      ${!a.builtin?`<button class="icb dl" onclick="deleteAdmin('${a.id||''}')"><i class="fa-solid fa-trash"></i>️</button>`:'<span style="font-size:.75rem;color:var(--muted)">Built-in</span>'}
    </div>`).join('') || '<p style="color:var(--muted);font-size:.85rem">No admin accounts.</p>';
}

function addAdminAccount() {
  const name=document.getElementById('newAdminName').value.trim();
  const user=document.getElementById('newAdminUser').value.trim();
  const pass=document.getElementById('newAdminPass').value;
  const role=document.getElementById('newAdminRole').value;
  if(!name||!user||!pass){showToast('All fields required','error');return;}
  if(!validateUsername('subAdmin', user)) return;
  if(admins.find(a=>a.username===user)){showToast('Username already exists','error');return;}
  admins.push({id:uid(),name,username:user,password:pass,role});
  save(K.admins,admins);
  ['newAdminName','newAdminUser','newAdminPass'].forEach(id=>document.getElementById(id).value='');
  renderAdminList(); showToast('Admin account created <i class="fa-solid fa-check"></i>','success');
}

function deleteAdmin(id) {
  if(!id||!confirm('Delete this admin account?'))return;
  admins=admins.filter(a=>a.id!==id);
  save(K.admins,admins); renderAdminList(); showToast('Account deleted','info');
}

// ═══════════════ DATA EXPORT/IMPORT ═══════════════
function exportAllData() {
  const data={students,subjects,teachers,classes,streams,exams,marks,settings,admins};
  const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob);
  a.download=`examinsight_backup_${new Date().toISOString().split('T')[0]}.json`; a.click();
  showToast('Data exported <i class="fa-solid fa-check"></i>','success');
}

function importData(input) {
  const file=input.files[0]; if(!file)return;
  const reader=new FileReader();
  reader.onload=e=>{
    try {
      const data=JSON.parse(e.target.result);
      if(data.students){students=data.students;saveStudents();}
      if(data.subjects){subjects=data.subjects;save(K.subjects,subjects);}
      if(data.teachers){teachers=data.teachers;save(K.teachers,teachers);}
      if(data.classes){classes=data.classes;save(K.classes,classes);}
      if(data.streams){streams=data.streams;save(K.streams,streams);}
      if(data.exams){exams=data.exams;save(K.exams,exams);}
      if(data.marks){marks=data.marks;saveMarks();}
      if(data.settings){settings=data.settings;save(K.settings,[settings]);}
      if(data.admins){admins=data.admins;save(K.admins,admins);}
      renderStudents();renderTeachers();renderSubjects();renderClasses();renderStreams();renderExamList();
      populateAllDropdowns();populateExamDropdowns();renderDashboard();loadSettings();
      showToast('Data imported successfully <i class="fa-solid fa-check"></i>','success');
    } catch(err){showToast('Invalid JSON file','error');console.error(err);}
  };
  reader.readAsText(file); input.value='';
}

async function clearAllData() {
  if(!confirm('DELETE ALL DATA? This cannot be undone!'))return;
  if(!confirm('Are you absolutely sure? All students, marks, and exams will be lost.'))return;
  Object.values(K).forEach(k=>localStorage.removeItem(k));
  // Also clear IDB-backed large arrays
  await idbDelete(K.marks);
  await idbDelete(K.students);
  location.reload();
}

// ═══════════════ ANALYSIS EXPORT ═══════════════
function exportAnalysisPDF() {
  try {
    const {jsPDF}=window.jspdf; const doc=new jsPDF();
    doc.setFontSize(16);doc.setFont(undefined,'bold');
    doc.text(`Charanas Analyzer — Analysis Report`,14,18);
    doc.setFontSize(10);doc.setFont(undefined,'normal');
    doc.text(`Generated: ${new Date().toLocaleDateString()} | School: ${settings.schoolName||''}`,14,26);

    const examId=document.getElementById('anExam')?.value;
    const exam=exams.find(e=>e.id===examId);
    if(exam){
      doc.setFontSize(12);doc.setFont(undefined,'bold');
      doc.text(`Exam: ${exam.name} — ${exam.term} ${exam.year}`,14,36);
      const subjectData=exam.subjectIds.map(sid=>{
        const sub=subjects.find(s=>s.id===sid);
        const vals=marks.filter(m=>m.examId===examId&&m.subjectId===sid).map(m=>m.score);
        const mn=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:0;
        return [sub?.name||'?',vals.length,mn.toFixed(1),vals.length?Math.max(...vals):'—',vals.length?Math.min(...vals):'—'];
      });
      doc.autoTable({startY:44,head:[['Subject','Count','Mean','Max','Min']],body:subjectData,theme:'striped',headStyles:{fillColor:[26,111,181]}});
    }
    doc.save('analysis_report.pdf');
    showToast('PDF exported <i class="fa-solid fa-check"></i>','success');
  } catch(e){showToast('PDF export error','error');console.error(e);}
}

function exportAnalysisExcel() {
  const examId=document.getElementById('anExam')?.value; if(!examId) return;
  const exam=exams.find(e=>e.id===examId);
  const rows=exam?.subjectIds.map(sid=>{
    const sub=subjects.find(s=>s.id===sid);
    const vals=marks.filter(m=>m.examId===examId&&m.subjectId===sid).map(m=>m.score);
    const mn=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:0;
    return {Subject:sub?.name,Count:vals.length,Mean:mn.toFixed(1),Highest:vals.length?Math.max(...vals):'',Lowest:vals.length?Math.min(...vals):''};
  })||[];
  const ws=XLSX.utils.json_to_sheet(rows); const wb=XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb,ws,'Analysis');
  XLSX.writeFile(wb,`analysis_${exam?.name||'exam'}.xlsx`);
}

