// ── Patch go() to handle timetable section ───────────────

function go(sec, el) {
  // STRICT TEACHER LOCKDOWN: teachers can only navigate to 'exams' (or 'fees' if class teacher)
  if (currentUser && currentUser.role === 'teacher') {
    const isClassTch = currentUserIsClassTeacher();
    const allowed = ['exams', ...(isClassTch ? ['fees'] : [])];
    if (!allowed.includes(sec)) return;
  }
  // BURSAR LOCKDOWN: bursars can only navigate to 'fees'
  if (currentUser && currentUser.role === 'bursar') {
    if (sec !== 'fees') return;
  }
  document.querySelectorAll('.sec').forEach(s => s.classList.remove('active'));
  document.querySelectorAll('.sn').forEach(n => n.classList.remove('active'));
  const s = document.getElementById('s-'+sec);
  if (s) s.classList.add('active');
  if (el) el.classList.add('active');
  document.getElementById('tbTitle').textContent = el ? el.querySelector('span').textContent : sec;
  if (window.innerWidth < 960) closeSidebar(); // auto-close on mobile only
  if (sec === 'dashboard')  renderDashboard();
  if (sec === 'exams')      { populateExamDropdowns(); renderPlatformExamMarkEntry(); renderSchoolPlatformResults(); try { renderCampusSelectorUI(); } catch(e) {} }
  if (sec === 'reports')    { populateReportDropdowns(); }
  if (sec === 'messaging')  { loadMsgRecipients(); }
  if (sec === 'fees')       { initFeesSection(); }
  if (sec === 'settings')   { renderTeacherPreferences(); }
  if (sec === 'people')     { initPeopleSection(); }
  if (sec === 'staffdetails') { initStaffDetailsSection(); }
  if (sec === 'platform')   { renderPlatformDashboard(); _navCfgMode='global'; navCfgSwitchMode('global'); platRenderNavConfig(); platRenderLiteModeConfig(); platLoadContactInputs(); themeRenderSwatches(); /* Activate first platform tab */ openPlatTab('platTab-schools', document.querySelector('#platTabBar .plat-tab-btn')); }
  if (sec === 'livechat')   { initLiveChatSection(); }
  if (sec === 'timetable')  {
    // Fire auto-sync event so the timetable pulls latest school data
    document.dispatchEvent(new CustomEvent('tt_sectionVisible'));
  }
  // Reset scroll AFTER all section-init calls have run.  Some init functions
  // (e.g. openPlatTab, initFeesSection) previously called scrollIntoView()
  // which moved the .main scrollbar before the user could see the top of the
  // page.  Deferring to the next task (setTimeout 0) guarantees this fires
  // after every synchronous init call AND after any scrollIntoView the browser
  // queues during layout.
  const mainEl = document.querySelector('.main');
  if (mainEl) {
    mainEl.scrollTop = 0;              // immediate reset (catches most cases)
    setTimeout(() => { mainEl.scrollTop = 0; }, 0); // deferred reset (catches post-render scroll)
  }
}

