// ── BOM Salary Functions ──
function calcBOMNet() {
  const basic  = parseFloat(document.getElementById('bomBasic')?.value)       || 0;
  const allow  = parseFloat(document.getElementById('bomAllowances')?.value)  || 0;
  const deduct = parseFloat(document.getElementById('bomDeductions')?.value)  || 0;
  const sha    = parseFloat(document.getElementById('bomSHA')?.value)         || 0;
  const nssf   = parseFloat(document.getElementById('bomNSSF')?.value)        || 0;
  const net    = basic + allow - deduct - sha - nssf;
  const netEl  = document.getElementById('bomNet');
  if (netEl) netEl.value = net.toFixed(2);
}

function saveBOMSalary() {
  const name  = document.getElementById('bomName')?.value.trim();
  const role  = document.getElementById('bomRole')?.value.trim();
  const type  = document.getElementById('bomType')?.value;
  const basic = parseFloat(document.getElementById('bomBasic')?.value)       || 0;
  const allow = parseFloat(document.getElementById('bomAllowances')?.value)  || 0;
  const deduct= parseFloat(document.getElementById('bomDeductions')?.value)  || 0;
  const sha   = parseFloat(document.getElementById('bomSHA')?.value)         || 0;
  const nssf  = parseFloat(document.getElementById('bomNSSF')?.value)        || 0;
  const net   = parseFloat(document.getElementById('bomNet')?.value)         || 0;
  const notes = document.getElementById('bomNotes')?.value.trim()            || '';
  const editId= document.getElementById('bomEditId')?.value                  || '';

  if (!name || !role || !basic) { alert('Please fill in Name, Role, and Basic Allowance.'); return; }

  const school = getCurrentSchool ? getCurrentSchool() : null;
  const key = school ? 'bomSalaries_' + school.id : 'bomSalaries';
  let data = JSON.parse(localStorage.getItem(key) || '[]');

  if (editId) {
    const idx = data.findIndex(r => r.id === editId);
    if (idx > -1) data[idx] = { ...data[idx], name, role, type, basic, allow, deduct, sha, nssf, net, notes };
  } else {
    data.push({ id: 'bom_' + Date.now(), name, role, type, basic, allow, deduct, sha, nssf, net, notes });
  }
  localStorage.setItem(key, JSON.stringify(data));
  clearBOMForm();
  renderBOMSalaryTable();
}

function clearBOMForm() {
  ['bomName','bomRole','bomBasic','bomAllowances','bomDeductions','bomSHA','bomNSSF','bomNet','bomNotes'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = (id === 'bomAllowances' || id === 'bomDeductions' || id === 'bomSHA' || id === 'bomNSSF') ? '0' : '';
  });
  const editEl = document.getElementById('bomEditId');
  if (editEl) editEl.value = '';
  const typeEl = document.getElementById('bomType');
  if (typeEl) typeEl.selectedIndex = 0;
}

function renderBOMSalaryTable() {
  const body = document.getElementById('bomBody');
  if (!body) return;
  const school = getCurrentSchool ? getCurrentSchool() : null;
  const key = school ? 'bomSalaries_' + school.id : 'bomSalaries';
  const data = JSON.parse(localStorage.getItem(key) || '[]');
  if (!data.length) {
    body.innerHTML = '<tr><td colspan="11" style="text-align:center;color:var(--muted);padding:2rem">No BOM salary records yet. Add one above.</td></tr>';
    return;
  }
  body.innerHTML = data.map((r, i) => `
    <tr>
      <td>${i+1}</td>
      <td>${r.name}</td>
      <td>${r.role}</td>
      <td>${r.type}</td>
      <td>KES ${Number(r.basic).toLocaleString()}</td>
      <td>KES ${Number(r.allow).toLocaleString()}</td>
      <td>KES ${Number(r.deduct).toLocaleString()}</td>
      <td>KES ${Number(r.sha).toLocaleString()}</td>
      <td>KES ${Number(r.nssf).toLocaleString()}</td>
      <td><strong>KES ${Number(r.net).toLocaleString()}</strong></td>
      <td>
        <button class="btn btn-outline btn-xs" onclick="editBOMSalary('${r.id}')"><i class="fa-solid fa-pen"></i></button>
        <button class="btn btn-danger btn-xs" onclick="deleteBOMSalary('${r.id}')"><i class="fa-solid fa-trash"></i></button>
      </td>
    </tr>`).join('');
}

function editBOMSalary(id) {
  const school = getCurrentSchool ? getCurrentSchool() : null;
  const key = school ? 'bomSalaries_' + school.id : 'bomSalaries';
  const data = JSON.parse(localStorage.getItem(key) || '[]');
  const r = data.find(x => x.id === id);
  if (!r) return;
  document.getElementById('bomEditId').value  = r.id;
  document.getElementById('bomName').value    = r.name;
  document.getElementById('bomRole').value    = r.role;
  document.getElementById('bomType').value    = r.type;
  document.getElementById('bomBasic').value   = r.basic;
  document.getElementById('bomAllowances').value = r.allow;
  document.getElementById('bomDeductions').value = r.deduct;
  document.getElementById('bomSHA').value     = r.sha;
  document.getElementById('bomNSSF').value    = r.nssf;
  document.getElementById('bomNotes').value   = r.notes;
  calcBOMNet();
  openSalarySubTab('tabSalaryBOM', document.getElementById('tbSalaryBOM'));
}

function deleteBOMSalary(id) {
  if (!confirm('Delete this BOM salary record?')) return;
  const school = getCurrentSchool ? getCurrentSchool() : null;
  const key = school ? 'bomSalaries_' + school.id : 'bomSalaries';
  let data = JSON.parse(localStorage.getItem(key) || '[]');
  data = data.filter(r => r.id !== id);
  localStorage.setItem(key, JSON.stringify(data));
  renderBOMSalaryTable();
}

function exportBOMSalaryCSV() {
  const school = getCurrentSchool ? getCurrentSchool() : null;
  const key = school ? 'bomSalaries_' + school.id : 'bomSalaries';
  const data = JSON.parse(localStorage.getItem(key) || '[]');
  const rows = [['Name','Role','Type','Basic','Allowances','Deductions','SHA','NSSF','Net Amount']];
  data.forEach(r => rows.push([r.name, r.role, r.type, r.basic, r.allow, r.deduct, r.sha, r.nssf, r.net]));
  const csv = rows.map(r => r.join(',')).join('\n');
  const a = document.createElement('a');
  a.href = 'data:text/csv,' + encodeURIComponent(csv);
  a.download = 'bom_salary_records.csv';
  a.click();
}


// ── Populate Fees Filter Dropdowns ──
function populateFeesDropdowns() {
  const isTeacher    = currentUser && currentUser.role === 'teacher';
  const isClassTch   = isTeacher && currentUserIsClassTeacher();
  const myStreamIds  = isClassTch ? getMyClassTeacherStreams().map(s => s.id) : [];
  const myClassIds   = isClassTch ? [...new Set(getMyClassTeacherStreams().map(s => s.classId))] : null;
  const teacherStreamIds = isTeacher ? getClassTeacherStreamIds(currentUser.teacherId) : [];
  const teacherClassIds  = isTeacher ? [...new Set(teacherStreamIds.map(sid => { const s=streams.find(x=>x.id===sid); return s?s.classId:null; }).filter(Boolean))] : null;

  // Determine visible classes (apply fee sync settings, then class-teacher filter)
  // Class teachers bypass fee-sync gating — they always see their own stream's class
  const feeSyncedClasses = isClassTch ? classes : getFeeVisibleClasses();
  const visibleClasses = myClassIds
    ? feeSyncedClasses.filter(c => myClassIds.includes(c.id))
    : (teacherClassIds ? feeSyncedClasses.filter(c => teacherClassIds.includes(c.id)) : feeSyncedClasses);

  // Collect all years from structures + records
  const years = [...new Set([
    ...feeStructures.map(f => f.year),
    ...feeRecords.map(r => r.year),
    String(new Date().getFullYear())
  ])].sort((a,b)=>b-a);

  const classOptions = '<option value="">All Classes</option>' + visibleClasses.map(c=>`<option value="${c.id}">${c.name}</option>`).join('');
  const yearOptions  = '<option value="">All Years</option>'  + years.map(y=>`<option value="${y}">${y}</option>`).join('');

  ['fovClass','fsbClass','fremClass','frctClass'].forEach(id => {
    const el = document.getElementById(id); if (el) el.innerHTML = classOptions;
  });

  // Overview stream filter — class teacher only sees their streams
  const fovStreamEl = document.getElementById('fovStream');
  if (fovStreamEl) {
    const visibleStreams = isClassTch
      ? streams.filter(s => myStreamIds.includes(s.id))
      : getFeeVisibleStreams('');
    fovStreamEl.innerHTML = '<option value="">All Streams</option>' +
      visibleStreams.map(s => `<option value="${s.id}">${s.name}</option>`).join('');
  }

  // Student Balances stream filter — class teacher locked to their streams
  const fsbStreamEl = document.getElementById('fsbStream');
  if (fsbStreamEl) {
    if (isClassTch && myStreamIds.length) {
      const myStreamObjs = streams.filter(s => myStreamIds.includes(s.id));
      fsbStreamEl.innerHTML = '<option value="">All My Streams</option>' +
        myStreamObjs.map(s => `<option value="${s.id}">${s.name}</option>`).join('');
      // Auto-select if only one stream
      if (myStreamIds.length === 1) fsbStreamEl.value = myStreamIds[0];
    } else {
      fsbStreamEl.innerHTML = '<option value="">All Streams</option>' +
        streams.map(s => `<option value="${s.id}">${s.name}</option>`).join('');
    }
  }
  ['fovYear','fsbYear','fremYear'].forEach(id => {
    const el = document.getElementById(id); if (el) el.innerHTML = yearOptions;
  });

  // Fee structure & payment form class dropdowns
  const strictClassOptions = '<option value="">— Select Class —</option>' + visibleClasses.map(c=>`<option value="${c.id}">${c.name}</option>`).join('');
  ['fstrClass','fpClass'].forEach(id => {
    const el = document.getElementById(id); if (el) el.innerHTML = strictClassOptions;
  });
  // Repopulate fstrStream if a class is already selected
  onFstrClassChange();

  // Year dropdowns for payment form
  const yearSelectOptions = years.map(y=>`<option value="${y}">${y}</option>`).join('');
  const fpYear = document.getElementById('fpYear'); if (fpYear) fpYear.innerHTML = yearSelectOptions;

  // Default current term in filters
  const curTerm = settings.currentTerm || 'Term 1';
  ['fovTerm','fsbTerm','fremTerm','fpTerm','frctTerm'].forEach(id => {
    const el = document.getElementById(id);
    if (el && el.value === '') {
      for (const opt of el.options) { if (opt.value === curTerm) { opt.selected = true; break; } }
    }
  });
  const curYear = String(settings.currentYear || new Date().getFullYear());
  ['fovYear','fsbYear','fremYear','fpYear'].forEach(id => {
    const el = document.getElementById(id);
    if (el) { for (const opt of el.options) { if (opt.value === curYear) { opt.selected = true; break; } } }
  });
}

// ── Populate Staff Dropdowns (Finances: Salary, Payslips) ──────────
function populateStaffDropdowns() {
  const staff = loadStaffDetails();
  const opts  = '<option value="">— Select Staff —</option>' +
    staff.map(s => `<option value="${s.id}">${s.name}${s.role ? ' — ' + s.role : ''}</option>`).join('');
  const ss = document.getElementById('ssStaff');
  if (ss) { const v = ss.value; ss.innerHTML = opts; if (v) ss.value = v; }
  const ps = document.getElementById('psStaff');
  if (ps) { const v = ps.value; ps.innerHTML = opts; if (v) ps.value = v; }
  const ph = document.getElementById('psHistStaff');
  if (ph) {
    const v = ph.value;
    ph.innerHTML = '<option value="">All Staff</option>' +
      staff.map(s => `<option value="${s.id}">${s.name}</option>`).join('');
    if (v) ph.value = v;
  }
  if (typeof sdpPopulateSalaryStaffDropdown === 'function') sdpPopulateSalaryStaffDropdown();
}

// ── Init Fees Section ──
function initFeesSection() {
  // Ensure Finance main panel defaults to Fees
  openFinanceMainTab('financeFees', document.getElementById('fmtFees'));
  loadFees();
  populateFeesDropdowns();
  populateStaffDropdowns(); // populate staff selects in Salary/Payslip tabs
  renderStaffSalaryTable();
  renderBOMSalaryTable();
  renderPayslipHistory();

  const role      = currentUser && currentUser.role;
  const isFullFees = role === 'superadmin' || role === 'admin' || role === 'principal' || role === 'bursar';
  const isTeacher  = role === 'teacher';
  const isClassTch = isTeacher && currentUserIsClassTeacher();

  // Full-fees users: all tabs visible
  // Class teacher: Overview + Student Balances + Record Payment (scoped to their stream)
  // Regular teacher: should never reach here (no fees link), but guard anyway
  const tabs = {
    tbFeeStructure : isFullFees,
    tbFeePayments  : isFullFees || isClassTch,
    tbFeeReminders : isFullFees,
    tbFeeReceipts  : isFullFees,
    tbFeeImport    : isFullFees,
    tbFeeStudents  : isFullFees || isClassTch,
    tbFeeSync      : isFullFees,
    tbFeeOverview  : true,
  };
  Object.entries(tabs).forEach(([id, show]) => {
    const el = document.getElementById(id);
    if (el) el.style.display = show ? '' : 'none';
  });

  // Admin stats bar: full-fees roles only
  const statsBar = document.getElementById('feesAdminStats');
  if (statsBar) statsBar.style.display = isFullFees ? '' : 'none';

  // If current active tab is now hidden, fall back to Overview
  const activeTab = document.querySelector('#feesTabBar .tb.active');
  if (activeTab && activeTab.style.display === 'none') {
    openFeesTab('tabFeeOverview', document.getElementById('tbFeeOverview'));
  }

  // Class teacher: auto-select their stream and lock the stream dropdown
  if (isClassTch) {
    const myStreams = getMyClassTeacherStreams();
    const myStreamIds = myStreams.map(s => s.id);
    const myClassIds = [...new Set(myStreams.map(s => s.classId))];

    // Lock fsbStream dropdown to class teacher's streams only
    const fsbStreamEl = document.getElementById('fsbStream');
    if (fsbStreamEl) {
      fsbStreamEl.innerHTML = '<option value="">All My Streams</option>' +
        myStreams.map(s => `<option value="${s.id}">${s.name}</option>`).join('');
      if (myStreams.length === 1) fsbStreamEl.value = myStreamIds[0];
      fsbStreamEl.disabled = false;
    }

    // Lock fsbClass dropdown to class teacher's classes only
    const fsbClassEl = document.getElementById('fsbClass');
    if (fsbClassEl) {
      const myClasses = classes.filter(c => myClassIds.includes(c.id));
      fsbClassEl.innerHTML = '<option value="">All My Classes</option>' +
        myClasses.map(c => `<option value="${c.id}">${c.name}</option>`).join('');
      if (myClasses.length === 1) fsbClassEl.value = myClasses[0].id;
    }

    // Overview: lock stream dropdown too
    const fovStreamEl = document.getElementById('fovStream');
    if (fovStreamEl) {
      fovStreamEl.innerHTML = '<option value="">All My Streams</option>' +
        myStreams.map(s => `<option value="${s.id}">${s.name}</option>`).join('');
      if (myStreams.length === 1) fovStreamEl.value = myStreamIds[0];
    }
    const fovClassEl = document.getElementById('fovClass');
    if (fovClassEl) {
      const myClasses = classes.filter(c => myClassIds.includes(c.id));
      fovClassEl.innerHTML = '<option value="">All My Classes</option>' +
        myClasses.map(c => `<option value="${c.id}">${c.name}</option>`).join('');
      if (myClasses.length === 1) fovClassEl.value = myClasses[0].id;
    }
  }

  renderFeeOverview();
  if (isClassTch) renderStudentBalances();
}


// ═══════════════════════════════════════════
// FEE CLASS & STREAM SYNC SETTINGS
// ═══════════════════════════════════════════
function renderFeeSyncSettings() {
  const container = document.getElementById('feeSyncSettingsBody');
  if (!container) return;

  const syncedClassIds  = getFeeSyncedClassIds();  // null = all enabled
  const syncedStreamIds = getFeeSyncedStreamIds(); // null = all enabled

  let html = `
    <p style="font-size:.85rem;color:var(--muted);margin-bottom:1rem">
      Select which classes and streams appear in the Fees section.
      Deselected classes/streams will be hidden from all fee forms and reports.
    </p>`;

  if (!classes.length) {
    html += '<p style="color:var(--muted)">No classes found. Add classes first.</p>';
    container.innerHTML = html;
    return;
  }

  classes.forEach(cls => {
    const clsEnabled = !syncedClassIds || syncedClassIds.includes(cls.id);
    const clsStreams  = streams.filter(s => s.classId === cls.id);
    html += `
      <div class="fee-sync-class-block" style="margin-bottom:1.2rem;padding:1rem;border:1px solid var(--border);border-radius:8px">
        <label style="display:flex;align-items:center;gap:.6rem;font-weight:700;font-size:.95rem;cursor:pointer;margin-bottom:.5rem">
          <input type="checkbox" class="fee-sync-cls-chk" data-cls-id="${cls.id}"
            ${clsEnabled ? 'checked' : ''}
            onchange="onFeeSyncClassToggle(this)"/>
          <i class="fa-solid fa-school" style="color:var(--primary)"></i> ${cls.name}
        </label>`;

    if (clsStreams.length > 0) {
      html += `<div class="fee-sync-streams" id="feeSyncStreams_${cls.id}" style="margin-left:1.8rem;display:flex;flex-wrap:wrap;gap:.5rem">`;
      clsStreams.forEach(s => {
        const sEnabled = !syncedStreamIds || syncedStreamIds.includes(s.id);
        html += `
          <label style="display:flex;align-items:center;gap:.4rem;font-size:.85rem;cursor:pointer;
                        background:var(--surface);padding:.3rem .7rem;border-radius:6px;border:1px solid var(--border)">
            <input type="checkbox" class="fee-sync-str-chk" data-str-id="${s.id}"
              ${sEnabled && clsEnabled ? 'checked' : ''} ${!clsEnabled ? 'disabled' : ''}/>
            <i class="fa-solid fa-layer-group" style="font-size:.75rem;color:var(--muted)"></i> ${s.name}
          </label>`;
      });
      html += '</div>';
    } else {
      html += `<div style="margin-left:1.8rem;font-size:.8rem;color:var(--muted)">No streams defined for this class.</div>`;
    }
    html += '</div>';
  });

  html += `
    <div style="display:flex;gap:.5rem;margin-top:.5rem;flex-wrap:wrap">
      <button class="btn btn-primary btn-sm" onclick="applyFeeSyncSettings()">
        <i class="fa-solid fa-floppy-disk"></i> Save Sync Settings
      </button>
      <button class="btn btn-outline btn-sm" onclick="resetFeeSyncSettings()">
        <i class="fa-solid fa-rotate-left"></i> Enable All (Reset)
      </button>
    </div>`;

  container.innerHTML = html;
}

function onFeeSyncClassToggle(chk) {
  const clsId = chk.dataset.clsId;
  const block  = document.getElementById('feeSyncStreams_' + clsId);
  if (!block) return;
  block.querySelectorAll('.fee-sync-str-chk').forEach(s => {
    s.disabled = !chk.checked;
    if (!chk.checked) s.checked = false;
    else s.checked = true;
  });
}

function applyFeeSyncSettings() {
  const classIds  = [...document.querySelectorAll('.fee-sync-cls-chk:checked')].map(el => el.dataset.clsId);
  const streamIds = [...document.querySelectorAll('.fee-sync-str-chk:checked')].map(el => el.dataset.strId);
  saveFeeSyncSettings(classIds, streamIds);
  populateFeesDropdowns();
  showToast('Fee sync settings saved <i class="fa-solid fa-check"></i>', 'success');
}

function resetFeeSyncSettings() {
  localStorage.removeItem(schoolPrefix() + K_FEES_SYNC_CLASSES);
  localStorage.removeItem(schoolPrefix() + K_FEES_SYNC_STREAMS);
  renderFeeSyncSettings();
  populateFeesDropdowns();
  showToast('All classes and streams enabled for fees', 'info');
}

// ═══════════════════════════════════════════
// OVERVIEW
// ═══════════════════════════════════════════
function onFovClassChange() {
  const classId = document.getElementById('fovClass')?.value || '';
  const streamSel = document.getElementById('fovStream');
  if (streamSel) {
    const prevStream = streamSel.value;
    const _isCT_fov = currentUser && currentUser.role === 'teacher' && currentUserIsClassTeacher();
    const classStreams = classId
      ? (_isCT_fov ? streams.filter(s => s.classId === classId) : getFeeVisibleStreams(classId))
      : (_isCT_fov ? streams : getFeeVisibleStreams(''));
    streamSel.innerHTML = '<option value="">All Streams</option>' +
      classStreams.map(s => `<option value="${s.id}">${s.name}</option>`).join('');
    // Preserve selection if still valid
    if (prevStream && classStreams.find(s => s.id === prevStream)) streamSel.value = prevStream;
  }
  renderFeeOverview();
}

// Returns the effective totalFee for a fee record:
// If the record's totalFee is 0 (e.g. created before a fee structure was set),
// fall back to the current fee structure for that student/class/term/year.
function getEffectiveTotalFee(rec) {
  const stored = parseFloat(rec.totalFee || 0);
  if (stored > 0) return stored;
  const stu = students.find(s => s.id === rec.studentId);
  const struct = stu
    ? getFeeStructureForStudent(stu, rec.term, rec.year)
    : getFeeStructure(rec.classId, rec.term, rec.year);
  return struct ? parseFloat(struct.totalFee || 0) : 0;
}

function renderFeeOverview() {
  loadFees();
  const filterClass  = document.getElementById('fovClass')?.value  || '';
  const filterStream = document.getElementById('fovStream')?.value || '';
  const filterTerm   = document.getElementById('fovTerm')?.value   || '';
  const filterYear   = document.getElementById('fovYear')?.value   || '';

  const isTeacher = currentUser && currentUser.role === 'teacher';
  const isFullFeesRole = currentUser && (currentUser.role==='superadmin'||currentUser.role==='admin'||currentUser.role==='principal'||currentUser.role==='bursar');
  const isClassTch = isTeacher && currentUserIsClassTeacher();
  const myStreamIds = isClassTch ? getMyClassTeacherStreams().map(s => s.id) : null;
  const teacherClassIds = (isTeacher && !isFullFeesRole)
    ? [...new Set(getClassTeacherStreamIds(currentUser.teacherId).map(sid => { const s=streams.find(x=>x.id===sid); return s?s.classId:null; }).filter(Boolean))]
    : null;

  // Class teacher: force stream filter to their stream(s) — override any dropdown value
  let effectiveStreamFilter = filterStream;
  if (isClassTch && myStreamIds && myStreamIds.length) {
    if (!effectiveStreamFilter || !myStreamIds.includes(effectiveStreamFilter)) {
      effectiveStreamFilter = myStreamIds.length === 1 ? myStreamIds[0] : '';
    }
  }

  // Class teachers bypass fee-sync gating — their class is always visible
  const feeSyncedCls = isClassTch ? classes : getFeeVisibleClasses();
  let visibleClasses = teacherClassIds
    ? feeSyncedCls.filter(c => teacherClassIds.includes(c.id))
    : feeSyncedCls;
  if (filterClass) visibleClasses = visibleClasses.filter(c => c.id === filterClass);

  // If stream filter active but no class filter, auto-narrow classes to those containing that stream
  if (effectiveStreamFilter && !filterClass) {
    const streamObj = streams.find(s => s.id === effectiveStreamFilter);
    if (streamObj) visibleClasses = visibleClasses.filter(c => c.id === streamObj.classId);
  }

  // Toggle stream column header visibility
  const streamHeader = document.getElementById('fovStreamHeader');
  if (streamHeader) streamHeader.style.display = filterStream ? '' : 'none';

  // Build summary — per stream if stream filter active, else per class
  let totalExpected=0, totalCollected=0, totalOutstanding=0, totalStudents=0;
  const rows = [];

  visibleClasses.forEach(cls => {
    // Determine which streams to show
    // Streams visible for this class — class teacher always limited to their own streams
    // Class teacher: all streams of their class are visible (ignore fee sync)
    let clsStreams = effectiveStreamFilter
      ? streams.filter(s => s.id === effectiveStreamFilter && s.classId === cls.id)
      : (isClassTch ? streams.filter(s => s.classId === cls.id) : getFeeVisibleStreams(cls.id));
    if (myStreamIds) clsStreams = clsStreams.filter(s => myStreamIds.includes(s.id));

    if (!clsStreams.length) return; // no accessible streams in this class

    if (effectiveStreamFilter || isClassTch) {
      // Stream-level rows (always for class teachers, or when stream filter active)
      clsStreams.forEach(stream => {
        const streamStudents = students.filter(s => s.classId === cls.id && s.streamId === stream.id);
        let expected=0, collected=0;
        streamStudents.forEach(stu => {
          const recs = feeRecords.filter(r => r.studentId===stu.id
            && (!filterTerm || r.term===filterTerm)
            && (!filterYear || String(r.year)===filterYear));
          recs.forEach(r => { expected += getEffectiveTotalFee(r); collected += getRecordTotalPaid(r); });
          if (!recs.length) {
            const structs = feeStructures.filter(f => f.classId===cls.id
              && (!f.streamId || f.streamId===stream.id)
              && (!filterTerm || f.term===filterTerm)
              && (!filterYear || String(f.year)===filterYear));
            structs.forEach(s => { expected += parseFloat(s.totalFee||0); });
          }
        });
        const outstanding = expected - collected;
        const pct = expected > 0 ? Math.round(collected/expected*100) : 0;
        totalExpected    += expected;
        totalCollected   += collected;
        totalOutstanding += outstanding;
        totalStudents    += streamStudents.length;
        rows.push({ cls, stream, students: streamStudents.length, expected, collected, outstanding, pct });
      });
    } else {
      // Class-level rows (original behaviour)
      const classStudents = students.filter(s => s.classId === cls.id);
      let expected=0, collected=0;
      classStudents.forEach(stu => {
        const recs = feeRecords.filter(r => r.studentId===stu.id
          && (!filterTerm || r.term===filterTerm)
          && (!filterYear || String(r.year)===filterYear));
        recs.forEach(r => { expected += getEffectiveTotalFee(r); collected += getRecordTotalPaid(r); });
        if (!recs.length) {
          const structs = feeStructures.filter(f => f.classId===cls.id
            && (!filterTerm || f.term===filterTerm)
            && (!filterYear || String(f.year)===filterYear));
          structs.forEach(s => { expected += parseFloat(s.totalFee||0); });
        }
      });
      const outstanding = expected - collected;
      const pct = expected > 0 ? Math.round(collected/expected*100) : 0;
      totalExpected    += expected;
      totalCollected   += collected;
      totalOutstanding += outstanding;
      totalStudents    += classStudents.length;
      rows.push({ cls, stream: null, students: classStudents.length, expected, collected, outstanding, pct });
    }
  });

  // Stats cards
  const statsEl = document.getElementById('feeOverviewStats');
  if (statsEl) {
    statsEl.innerHTML = `
      <div class="fee-ov-stat-row">
        <div class="fee-stat-card fsc-blue"><div class="fsc-ico"><i class="fa-solid fa-users"></i></div><div class="fsc-val">${totalStudents}</div><div class="fsc-lbl">Total Students</div></div>
        <div class="fee-stat-card fsc-teal"><div class="fsc-ico"><i class="fa-solid fa-coins"></i></div><div class="fsc-val">KES ${totalExpected.toLocaleString()}</div><div class="fsc-lbl">Total Expected</div></div>
        <div class="fee-stat-card fsc-green"><div class="fsc-ico"><i class="fa-solid fa-circle-check"></i></div><div class="fsc-val">KES ${totalCollected.toLocaleString()}</div><div class="fsc-lbl">Total Collected</div></div>
        <div class="fee-stat-card fsc-red"><div class="fsc-ico"><i class="fa-solid fa-triangle-exclamation"></i>️</div><div class="fsc-val">KES ${totalOutstanding.toLocaleString()}</div><div class="fsc-lbl">Outstanding</div></div>
        <div class="fee-stat-card fsc-amber"><div class="fsc-ico"><i class="fa-solid fa-chart-bar"></i></div><div class="fsc-val">${totalExpected>0?Math.round(totalCollected/totalExpected*100):0}%</div><div class="fsc-lbl">Collection Rate</div></div>
      </div>`;
  }

  // Admin global stats bar
  const adminBar = document.getElementById('feesAdminStats');
  if (adminBar && (currentUser.role==='superadmin'||currentUser.role==='admin')) {
    adminBar.innerHTML = `
      <div class="stat-card sc-blue"><div class="sc-num">KES ${totalExpected.toLocaleString()}</div><div class="sc-lbl">Expected</div><div class="sc-ico"><i class="fa-solid fa-coins"></i></div></div>
      <div class="stat-card sc-green"><div class="sc-num">KES ${totalCollected.toLocaleString()}</div><div class="sc-lbl">Collected</div><div class="sc-ico"><i class="fa-solid fa-circle-check"></i></div></div>
      <div class="stat-card sc-amber"><div class="sc-num">KES ${totalOutstanding.toLocaleString()}</div><div class="sc-lbl">Outstanding</div><div class="sc-ico"><i class="fa-solid fa-triangle-exclamation"></i>️</div></div>
      <div class="stat-card sc-teal"><div class="sc-num">${totalExpected>0?Math.round(totalCollected/totalExpected*100):0}%</div><div class="sc-lbl">Collection Rate</div><div class="sc-ico"><i class="fa-solid fa-chart-bar"></i></div></div>`;
  }

  // Table
  const tbody = document.getElementById('feeOverviewBody');
  if (tbody) {
    tbody.innerHTML = rows.length ? rows.map(r => `
      <tr>
        <td><strong>${r.cls.name}</strong></td>
        ${r.stream ? `<td>${r.stream.name}</td>` : (filterStream ? '<td>—</td>' : '')}
        <td>${r.students}</td>
        <td>KES ${r.expected.toLocaleString()}</td>
        <td>KES ${r.collected.toLocaleString()}</td>
        <td style="color:${r.outstanding>0?'var(--danger)':'var(--success)'}"><strong>KES ${r.outstanding.toLocaleString()}</strong></td>
        <td>
          <div style="display:flex;align-items:center;gap:.5rem">
            <div style="flex:1;height:8px;background:var(--border);border-radius:4px;overflow:hidden">
              <div style="height:100%;width:${r.pct}%;background:${r.pct>=80?'var(--success)':r.pct>=50?'#f59e0b':'var(--danger)'};border-radius:4px"></div>
            </div>
            <span style="font-size:.8rem;font-weight:600;min-width:2.5rem">${r.pct}%</span>
          </div>
        </td>
        <td>
          <button class="btn btn-sm btn-outline" onclick="filterToClassStream('${r.cls.id}','${r.stream?r.stream.id:''}')">View Students</button>
        </td>
      </tr>`).join('')
    : '<tr><td colspan="8" style="text-align:center;color:var(--muted);padding:2rem">No fee data found. Set up fee structures first.</td></tr>';
  }
}

function filterToClass(classId) {
  openFeesTab('tabFeeStudents', document.getElementById('tbFeeStudents'));
  setTimeout(() => {
    const el = document.getElementById('fsbClass');
    if (el) { el.value = classId; renderStudentBalances(); }
  }, 100);
}
function filterToClassStream(classId, streamId) {
  openFeesTab('tabFeeStudents', document.getElementById('tbFeeStudents'));
  setTimeout(() => {
    const cls = document.getElementById('fsbClass');
    if (cls) { cls.value = classId; }
    if (streamId) {
      // trigger stream population then set stream
      if (typeof onFsbClassChange === 'function') onFsbClassChange();
      setTimeout(() => {
        const str = document.getElementById('fsbStream');
        if (str) str.value = streamId;
        renderStudentBalances();
      }, 80);
    } else {
      renderStudentBalances();
    }
  }, 100);
}

// ═══════════════════════════════════════════
// FEE STRUCTURE
// ═══════════════════════════════════════════
function addFstrBreakdownRow() {
  const container = document.getElementById('fstrBreakdownRows');
  const div = document.createElement('div');
  div.className = 'frow c2 fstr-row';
  div.style.cssText = 'margin-bottom:.5rem;gap:.5rem';
  div.innerHTML = `
    <div class="fg"><input type="text" placeholder="Item (e.g. Tuition)" style="padding:.4rem .6rem;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text);width:100%;font-size:.85rem" class="fstr-item"/></div>
    <div class="fg" style="display:flex;gap:.5rem">
      <input type="number" placeholder="Amount (KES)" min="0" style="padding:.4rem .6rem;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text);width:100%;font-size:.85rem" class="fstr-amt"/>
      <button class="btn btn-sm btn-danger-sm" onclick="this.closest('.fstr-row').remove()"><i class="fa-solid fa-xmark"></i></button>
    </div>`;
  container.appendChild(div);
}

function onFstrClassChange() {
  const classId = document.getElementById('fstrClass')?.value;
  const streamSel = document.getElementById('fstrStream');
  if (!streamSel) return;
  const classStreams = getFeeVisibleStreams(classId);
  streamSel.innerHTML = '<option value="">— Whole Class (no stream split) —</option>' +
    classStreams.map(s => `<option value="${s.id}">${s.name}</option>`).join('');
}

function clearFstrForm() {
  document.getElementById('fstrEditId').value = '';
  document.getElementById('fstrClass').value = '';
  const streamSel = document.getElementById('fstrStream');
  if (streamSel) streamSel.innerHTML = '<option value="">— Whole Class (no stream split) —</option>';
  document.getElementById('fstrTotal').value = '';
  document.getElementById('fstrBreakdownRows').innerHTML = '';
}

function saveFeeStructure() {
  const r = currentUser && currentUser.role;
  if (!(r==='superadmin'||r==='admin'||r==='principal'||r==='bursar')) { showToast('Only administrators can edit fee structures','error'); return; }
  loadFees();
  const editId   = document.getElementById('fstrEditId').value;
  const classId  = document.getElementById('fstrClass').value;
  const streamId = document.getElementById('fstrStream')?.value || '';
  const term     = document.getElementById('fstrTerm').value;
  const year     = document.getElementById('fstrYear').value;
  const total    = parseFloat(document.getElementById('fstrTotal').value);

  if (!classId || !term || !year || isNaN(total) || total <= 0) {
    showToast('Please fill Class, Term, Year and a valid Total Fee', 'error'); return;
  }

  // Collect breakdown rows
  const breakdown = [];
  document.querySelectorAll('.fstr-row').forEach(row => {
    const item = row.querySelector('.fstr-item')?.value.trim();
    const amt  = parseFloat(row.querySelector('.fstr-amt')?.value||0);
    if (item && amt > 0) breakdown.push({ item, amount: amt });
  });

  const structObj = { classId, term, year: String(year), totalFee: total, breakdown };
  if (streamId) structObj.streamId = streamId; // stream-specific

  if (editId) {
    const i = feeStructures.findIndex(f => f.id === editId);
    if (i > -1) feeStructures[i] = { ...feeStructures[i], ...structObj };
  } else {
    // Check for duplicate (same class + stream combo)
    const dup = feeStructures.find(f =>
      f.classId===classId && (f.streamId||'')===streamId && f.term===term && String(f.year)===String(year));
    if (dup) { showToast('A structure already exists for this class/stream/term/year. Edit it instead.', 'error'); return; }
    feeStructures.push({ id: uid(), ...structObj });
  }

  // Sync existing fee records that have totalFee=0 for this class/term/year
  // (records created before the fee structure was set, or when no structure existed)
  feeRecords.forEach(rec => {
    if (rec.term !== term || String(rec.year) !== String(year)) return;
    if (rec.classId !== classId) return;
    // Stream-specific structure: only apply to students in that stream
    if (streamId) {
      const recStu = students.find(s => s.id === rec.studentId);
      if (!recStu || recStu.streamId !== streamId) return;
    }
    if (parseFloat(rec.totalFee || 0) === 0) {
      rec.totalFee = total;
    }
  });

  saveFees();
  clearFstrForm();
  renderFeeStructureList();
  populateFeesDropdowns();
  showToast('Fee structure saved <i class="fa-solid fa-check"></i>', 'success');
}

function renderFeeStructureList() {
  loadFees();
  const el = document.getElementById('feeStructureList');
  if (!el) return;
  if (!feeStructures.length) { el.innerHTML = '<p style="color:var(--muted)">No fee structures yet.</p>'; return; }

  el.innerHTML = feeStructures.map(f => {
    const cls    = classes.find(c => c.id === f.classId);
    const stream = f.streamId ? streams.find(s => s.id === f.streamId) : null;
    const scopeLabel = stream
      ? `<span class="badge b-teal" style="font-size:.65rem;margin-left:.4rem"><i class="fa-solid fa-layer-group"></i> ${stream.name}</span>`
      : `<span class="badge b-blue" style="font-size:.65rem;margin-left:.4rem">Whole Class</span>`;
    return `
      <div class="fee-struct-item">
        <div class="fsi-head">
          <div>
            <strong>${cls?.name || 'Unknown Class'}</strong>
            ${scopeLabel}
            <span class="badge" style="font-size:.65rem;margin-left:.2rem;background:var(--surface);color:var(--muted)">${f.term} ${f.year}</span>
          </div>
          <strong style="color:var(--primary)">KES ${parseFloat(f.totalFee).toLocaleString()}</strong>
        </div>
        ${f.breakdown && f.breakdown.length ? `
          <div class="fsi-breakdown">
            ${f.breakdown.map(b=>`<span>${b.item}: <strong>KES ${parseFloat(b.amount).toLocaleString()}</strong></span>`).join('')}
          </div>` : ''}
        <div class="fsi-actions">
          <button class="btn btn-sm btn-outline" onclick="editFeeStructure('${f.id}')"><i class="fa-solid fa-pen"></i>️ Edit</button>
          <button class="btn btn-sm btn-danger-sm" onclick="deleteFeeStructure('${f.id}')"><i class="fa-solid fa-trash"></i> Delete</button>
        </div>
      </div>`;
  }).join('');
}

function editFeeStructure(id) {
  loadFees();
  const f = feeStructures.find(x => x.id === id); if (!f) return;
  document.getElementById('fstrEditId').value = id;
  document.getElementById('fstrClass').value  = f.classId;
  document.getElementById('fstrTerm').value   = f.term;
  document.getElementById('fstrYear').value   = f.year;
  document.getElementById('fstrTotal').value  = f.totalFee;
  // Populate streams for this class, then set selected stream
  onFstrClassChange();
  setTimeout(() => {
    const streamSel = document.getElementById('fstrStream');
    if (streamSel && f.streamId) streamSel.value = f.streamId;
  }, 50);
  const container = document.getElementById('fstrBreakdownRows');
  container.innerHTML = '';
  (f.breakdown||[]).forEach(b => {
    addFstrBreakdownRow();
    const rows = container.querySelectorAll('.fstr-row');
    const last = rows[rows.length-1];
    last.querySelector('.fstr-item').value = b.item;
    last.querySelector('.fstr-amt').value  = b.amount;
  });
  document.querySelector('#tabFeeStructure').scrollIntoView({ behavior: 'smooth' });
}

function deleteFeeStructure(id) {
  if (!confirm('Delete this fee structure?')) return;
  loadFees();
  feeStructures = feeStructures.filter(f => f.id !== id);
  saveFees();
  renderFeeStructureList();
  showToast('Fee structure deleted', 'info');
}

// ═══════════════════════════════════════════
// PAYMENT RECORDING
// ═══════════════════════════════════════════
function initFeePaymentForm() {
  const today = new Date().toISOString().split('T')[0];
  const fpDate = document.getElementById('fpDate');
  if (fpDate && !fpDate.value) fpDate.value = today;
  populateFeesDropdowns();
  onFpClassChange();
  // Show scope notice for class teachers
  const fpNotice = document.getElementById('fpClassTeacherNotice');
  if (fpNotice) {
    const _isClassTch = currentUser && currentUser.role === 'teacher' && currentUserIsClassTeacher();
    fpNotice.style.display = _isClassTch ? '' : 'none';
    if (_isClassTch) {
      const myStreams = getMyClassTeacherStreams();
      fpNotice.innerHTML = `<i class="fa-solid fa-thumbtack"></i> <strong>Scoped to your stream${myStreams.length > 1 ? 's' : ''}:</strong> ${myStreams.map(s => s.name).join(', ')}. Only your stream's students are shown.`;
    }
  }
}

function onFpClassChange() {
  loadFees();
  const classId = document.getElementById('fpClass')?.value;
  const fpStudent = document.getElementById('fpStudent');
  if (!fpStudent) return;

  if (!classId) {
    fpStudent.innerHTML = '<option value="">— Select Student —</option>';
    document.getElementById('fpBalanceCard').style.display = 'none';
    return;
  }

  // Class teacher: restrict to their stream(s) only
  const isClassTch_fp = currentUser && currentUser.role === 'teacher' && currentUserIsClassTeacher();
  const myStreamIds_fp = isClassTch_fp ? getMyClassTeacherStreams().map(s => s.id) : null;
  const classStudents = students
    .filter(s => s.classId === classId && (!myStreamIds_fp || myStreamIds_fp.includes(s.streamId)))
    .sort((a,b) => a.name.localeCompare(b.name));
  fpStudent.innerHTML = '<option value="">— Select Student —</option>' + classStudents.map(s => `<option value="${s.id}">${s.name} (${s.adm})</option>`).join('');
  onFpStudentChange();
}

function onFpTermChange() {
  onFpStudentChange();
}

function onFpStudentChange() {
  loadFees();
  const stuId   = document.getElementById('fpStudent')?.value;
  const classId = document.getElementById('fpClass')?.value;
  const term    = document.getElementById('fpTerm')?.value;
  const year    = document.getElementById('fpYear')?.value;
  const card    = document.getElementById('fpBalanceCard');

  if (!stuId || !classId || !term || !year) {
    if (card) card.style.display = 'none'; return;
  }

  const stu_fp  = students.find(s => s.id === stuId);
  const struct  = stu_fp ? getFeeStructureForStudent(stu_fp, term, year) : getFeeStructure(classId, term, year);
  const rec    = feeRecords.find(r => r.studentId===stuId && r.term===term && String(r.year)===String(year));
  const totalFee = rec ? parseFloat(rec.totalFee||0) : (struct ? parseFloat(struct.totalFee||0) : 0);
  const paid     = rec ? getRecordTotalPaid(rec) : 0;
  const prevBal  = getPreviousBalance(stuId, term, year);
  const bal      = prevBal + totalFee - paid;

  const prevBalEl    = document.getElementById('fpPrevBalance');
  const prevBalRowEl = document.getElementById('fpPrevBalRow');
  if (prevBalEl) prevBalEl.textContent = `KES ${prevBal.toLocaleString()}`;
  if (prevBalRowEl) prevBalRowEl.style.display = prevBal > 0 ? 'flex' : 'none';

  document.getElementById('fpTotalFee').textContent  = `KES ${totalFee.toLocaleString()}`;
  document.getElementById('fpAmountPaid').textContent = `KES ${paid.toLocaleString()}`;
  document.getElementById('fpBalance').textContent    = `KES ${bal.toLocaleString()}`;
  document.getElementById('fpBalance').style.color    = bal > 0 ? 'var(--danger)' : 'var(--success)';
  if (card) card.style.display = 'block';
}

function recordFeePayment() {
  const r = currentUser && currentUser.role;
  if (!(r==='superadmin'||r==='admin'||r==='principal'||r==='bursar')) { showToast('Only administrators and the bursar can record payments','error'); return; }
  loadFees();
  const stuId   = document.getElementById('fpStudent')?.value;
  const classId = document.getElementById('fpClass')?.value;
  const term    = document.getElementById('fpTerm')?.value;
  const year    = document.getElementById('fpYear')?.value;
  const amount  = parseFloat(document.getElementById('fpAmount')?.value||0);
  const mode    = document.getElementById('fpMode')?.value || 'Cash';
  const date    = document.getElementById('fpDate')?.value || new Date().toISOString().split('T')[0];
  const notes   = document.getElementById('fpNotes')?.value || '';

  if (!stuId)   { showToast('Please select a student', 'error'); return; }
  if (!classId) { showToast('Please select a class', 'error'); return; }
  if (amount <= 0) { showToast('Please enter a valid amount', 'error'); return; }

  const stu_pay  = students.find(s => s.id === stuId);
  const struct   = stu_pay ? getFeeStructureForStudent(stu_pay, term, year) : getFeeStructure(classId, term, year);
  const totalFee = struct ? parseFloat(struct.totalFee||0) : 0;

  if (!totalFee) {
    showToast('No fee structure set for this class/stream/term/year. Create one first.', 'error'); return;
  }

  // Get or create record
  let rec = feeRecords.find(r => r.studentId===stuId && r.term===term && String(r.year)===String(year));
  if (!rec) {
    rec = { id: uid(), studentId: stuId, classId, term, year: String(year), totalFee, payments: [] };
    feeRecords.push(rec);
  }
  // Update totalFee from structure in case it changed
  rec.totalFee = totalFee;

  const prevBal   = getPreviousBalance(stuId, term, year);
  const balBefore = prevBal + getRecordBalance(rec);
  const receiptNo = genReceiptNo();
  const recordedBy = currentUser ? (currentUser.name || currentUser.username) : 'Unknown';
  const payment = { id: uid(), receiptNo, date, amount, mode, notes, prevBal, balanceBefore: balBefore, balanceAfter: balBefore - amount, recordedBy };
  rec.payments.push(payment);
  saveFees();

  // Build and show receipt
  const stu = students.find(s => s.id === stuId);
  const cls = classes.find(c => c.id === classId);
  lastReceiptHtml = buildReceiptHTML({ stu, cls, term, year, totalFee, payment, prevBal, balBefore, balAfter: balBefore - amount, receiptNo, date, mode, notes, amount, schoolName: settings.schoolName || 'School' });

  const previewEl = document.getElementById('receiptPreview');
  if (previewEl) previewEl.innerHTML = lastReceiptHtml;
  const actEl = document.getElementById('receiptActions');
  if (actEl) actEl.style.display = 'flex';

  // Reset amount
  const amtEl = document.getElementById('fpAmount'); if (amtEl) amtEl.value = '';
  const notesEl = document.getElementById('fpNotes'); if (notesEl) notesEl.value = '';
  onFpStudentChange();
  showToast(`Payment of KES ${amount.toLocaleString()} recorded <i class="fa-solid fa-check"></i> — Receipt ${receiptNo}`, 'success');

  // Auto-print receipt
  setTimeout(() => printLastReceipt(), 400);
}

function buildReceiptHTML({ stu, cls, term, year, totalFee, payment, prevBal, balBefore, balAfter, receiptNo, date, mode, notes, amount, schoolName }) {
  // prevBal: balance carried from previous term(s)
  // balBefore: total balance before this payment = prevBal + this term's unpaid fee
  if (prevBal === undefined) prevBal = 0;
  const d = new Date(date);
  const dateStr = d.toLocaleDateString('en-KE', { day:'2-digit', month:'long', year:'numeric' });
  const status = balAfter <= 0 ? '<span style="color:#16a34a;font-weight:700"><i class="fa-solid fa-circle-check"></i> FEES CLEARED</span>' : `<span style="color:#dc2626;font-weight:700"><i class="fa-solid fa-triangle-exclamation"></i>️ BALANCE: KES ${balAfter.toLocaleString()}</span>`;
  return `
    <div class="fee-receipt" id="feeReceiptPrint">
      <div class="rcpt-header">
        <div class="rcpt-logo">CA</div>
        <div class="rcpt-school">
          <strong>${schoolName}</strong>
          <div style="font-size:.75rem;color:#64748b">${settings.address || ''} ${settings.phone ? '| Tel: '+settings.phone : ''}</div>
          <div style="font-weight:700;color:#1a6fb5;font-size:.85rem;margin-top:.15rem">OFFICIAL FEE RECEIPT</div>
        </div>
        <div class="rcpt-no">
          <div style="font-size:.65rem;color:#64748b;text-transform:uppercase;letter-spacing:.05em">Receipt No.</div>
          <div style="font-size:1rem;font-weight:800;color:#1a6fb5">${receiptNo}</div>
          <div style="font-size:.72rem;color:#64748b">${dateStr}</div>
        </div>
      </div>
      <div class="rcpt-divider"></div>
      <div class="rcpt-body">
        <div class="rcpt-row"><span class="rcpt-lbl">Student Name</span><span class="rcpt-val">${stu?.name || '—'}</span></div>
        <div class="rcpt-row"><span class="rcpt-lbl">Admission No.</span><span class="rcpt-val">${stu?.adm || '—'}</span></div>
        <div class="rcpt-row"><span class="rcpt-lbl">Class</span><span class="rcpt-val">${cls?.name || '—'}</span></div>
        <div class="rcpt-row"><span class="rcpt-lbl">Term / Year</span><span class="rcpt-val">${term} — ${year}</span></div>
        <div class="rcpt-row"><span class="rcpt-lbl">This Term's Fee</span><span class="rcpt-val">KES ${parseFloat(totalFee).toLocaleString()}</span></div>
        ${prevBal > 0 ? `<div class="rcpt-row"><span class="rcpt-lbl">Previous Balance</span><span class="rcpt-val" style="color:#dc2626">KES ${parseFloat(prevBal).toLocaleString()}</span></div>` : ''}
        <div class="rcpt-row"><span class="rcpt-lbl">Total Balance Before Payment</span><span class="rcpt-val" style="color:#dc2626;font-weight:700">KES ${parseFloat(balBefore).toLocaleString()}</span></div>
        <div class="rcpt-divider-sm"></div>
        <div class="rcpt-row rcpt-paid-row">
          <span class="rcpt-lbl">Amount Paid</span>
          <span class="rcpt-val" style="color:#16a34a;font-size:1.1rem;font-weight:800">KES ${parseFloat(amount).toLocaleString()}</span>
        </div>
        <div class="rcpt-row"><span class="rcpt-lbl">Payment Mode</span><span class="rcpt-val">${mode}</span></div>
        ${notes ? `<div class="rcpt-row"><span class="rcpt-lbl">Reference</span><span class="rcpt-val">${notes}</span></div>` : ''}
        <div class="rcpt-divider-sm"></div>
        <div class="rcpt-row rcpt-bal-row">
          <span class="rcpt-lbl">Updated Balance</span>
          <span class="rcpt-val">${status}</span>
        </div>
      </div>
      <div class="rcpt-footer">
        <div class="rcpt-sig">Received by: ……………………………………</div>
        <div class="rcpt-sig">Cashier Stamp: ……………………………………</div>
      </div>
      <div style="text-align:center;font-size:.65rem;color:#94a3b8;margin-top:.5rem">This is a computer-generated receipt. No signature required. — ${schoolName}</div>
    </div>`;
}

function printLastReceipt() {
  if (!lastReceiptHtml) { showToast('No receipt to print','error'); return; }
  const win = window.open('', '_blank', 'width=520,height=750');
  win.document.write(`<!DOCTYPE html><html><head><title>Fee Receipt</title><style>
    *{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important;color-adjust:exact!important}
    @page{size:A5 portrait;margin:10mm}
    body{font-family:'Segoe UI',Arial,sans-serif;padding:1.5rem;color:#1e293b;background:#fff;margin:0}
    .fee-receipt{max-width:420px;margin:0 auto;border:2px solid #1a6fb5;border-radius:10px;padding:1.2rem;background:#fff}
    .rcpt-header{display:flex;gap:.75rem;align-items:flex-start;margin-bottom:.75rem}
    .rcpt-logo{width:40px;height:40px;background:linear-gradient(135deg,#1a6fb5,#0ea5e9);border-radius:8px;color:#fff;font-weight:800;font-size:.9rem;display:flex;align-items:center;justify-content:center}
    .rcpt-school{flex:1}.rcpt-school strong{font-size:.95rem;color:#1e293b}
    .rcpt-no{text-align:right;min-width:7rem}
    .rcpt-divider{border-top:2px dashed #1a6fb5;margin:.6rem 0}
    .rcpt-divider-sm{border-top:1px solid #e2e8f0;margin:.4rem 0}
    .rcpt-body{display:flex;flex-direction:column;gap:.3rem}
    .rcpt-row{display:flex;justify-content:space-between;align-items:center;font-size:.82rem;padding:.15rem 0}
    .rcpt-lbl{color:#64748b;font-size:.78rem}.rcpt-val{font-weight:600;color:#1e293b}
    .rcpt-paid-row{background:#f0fdf4!important;border-radius:6px;padding:.3rem .5rem;margin:.25rem 0}
    .rcpt-bal-row{background:#fef3c7!important;border-radius:6px;padding:.3rem .5rem}
    .rcpt-footer{display:flex;justify-content:space-between;margin-top:.75rem;padding-top:.5rem;border-top:1px solid #e2e8f0;font-size:.72rem;color:#94a3b8}
    @media print{
      body{padding:0}
      .fee-receipt{border:2px solid #1a6fb5!important;max-width:100%;border-radius:10px!important}
      .rcpt-logo{background:linear-gradient(135deg,#1a6fb5,#0ea5e9)!important}
      .rcpt-paid-row{background:#f0fdf4!important}
      .rcpt-bal-row{background:#fef3c7!important}
    }
  </style></head><body>${lastReceiptHtml}</body></html>`);
  win.document.close();
  setTimeout(() => { win.focus(); win.print(); }, 400);
}

// ═══════════════════════════════════════════
// STUDENT BALANCES
// ═══════════════════════════════════════════
function renderStudentBalances() {
  loadFees();
  const filterClass  = document.getElementById('fsbClass')?.value  || '';
  const filterTerm   = document.getElementById('fsbTerm')?.value   || '';
  const filterYear   = document.getElementById('fsbYear')?.value   || '';
  const filterStatus = document.getElementById('fsbStatus')?.value || '';
  const filterMinBal = parseFloat(document.getElementById('fsbMinBalance')?.value || '0') || 0;
  const search       = (document.getElementById('fsbSearch')?.value || '').toLowerCase();
  const filterStream = document.getElementById('fsbStream')?.value || '';

  const isTeacher = currentUser && currentUser.role === 'teacher';
  const isClassTch = isTeacher && currentUserIsClassTeacher();
  const isFullFeesRole = currentUser && (currentUser.role==='superadmin'||currentUser.role==='admin'||currentUser.role==='principal'||currentUser.role==='bursar');

  // Class teacher is strictly limited to their own streams
  const myStreamIds = isClassTch ? getMyClassTeacherStreams().map(s => s.id) : null;
  const teacherClassIds = (isTeacher && !isFullFeesRole)
    ? [...new Set(getClassTeacherStreamIds(currentUser.teacherId).map(sid => { const s=streams.find(x=>x.id===sid); return s?s.classId:null; }).filter(Boolean))]
    : null;

  const tbody = document.getElementById('feeStudentsBody');
  if (!tbody) return;

  // Build rows: one row per student per record
  let rows = [];
  feeRecords.forEach(rec => {
    if (filterTerm   && rec.term !== filterTerm)              return;
    if (filterYear   && String(rec.year) !== filterYear)      return;
    if (filterClass  && rec.classId !== filterClass)          return;
    if (teacherClassIds && !teacherClassIds.includes(rec.classId)) return;

    const stu = students.find(s => s.id === rec.studentId); if (!stu) return;
    // Class teacher: enforce stream restriction
    if (myStreamIds && !myStreamIds.includes(stu.streamId)) return;
    // Stream filter (from dropdown)
    if (filterStream && stu.streamId !== filterStream) return;
    // Skip if class not synced to fees (class teachers bypass this — they always see their stream)
    if (!isClassTch) {
      const feeSyncCls = getFeeSyncedClassIds();
      if (feeSyncCls && !feeSyncCls.includes(rec.classId)) return;
      const feeSyncStr = getFeeSyncedStreamIds();
      if (feeSyncStr && stu.streamId && !feeSyncStr.includes(stu.streamId)) return;
    }
    const cls = classes.find(c => c.id === rec.classId);
    const effectiveFee = getEffectiveTotalFee(rec);
    // If the stored totalFee was 0 but a structure now exists, update the record in-memory for correct display
    if (effectiveFee > 0 && parseFloat(rec.totalFee || 0) === 0) rec.totalFee = effectiveFee;
    const paid = getRecordTotalPaid(rec);
    const prevBal = getPreviousBalance(rec.studentId, rec.term, rec.year);
    const bal  = getRecordBalance(rec);
    const cumBal = prevBal + bal;
    const pct  = effectiveFee > 0 ? Math.round(paid/effectiveFee*100) : 0;
    const cumBalRounded = Math.round(cumBal * 100) / 100;
    let statusKey = cumBalRounded <= 0 ? 'cleared' : paid > 0 ? 'partial' : 'unpaid';

    if (filterStatus && statusKey !== filterStatus) return;
    if (filterMinBal > 0 && cumBal < filterMinBal) return;
    if (search && !stu.name.toLowerCase().includes(search) && !stu.adm.toLowerCase().includes(search)) return;

    rows.push({ rec, stu, cls, paid, bal, cumBal, pct, statusKey });
  });

  // Also add students with NO record if a structure exists for them
  const sbFeeSyncCls = getFeeSyncedClassIds();
  const sbFeeSyncStr = getFeeSyncedStreamIds();
  students.forEach(stu => {
    const clsId = stu.classId;
    if (teacherClassIds && !teacherClassIds.includes(clsId)) return;
    if (filterClass && clsId !== filterClass) return;
    // Class teacher: enforce stream restriction on "no record" students too
    if (myStreamIds && !myStreamIds.includes(stu.streamId)) return;
    // Respect fee sync settings (class teachers bypass — they always see their stream)
    if (!isClassTch) {
      if (sbFeeSyncCls && !sbFeeSyncCls.includes(clsId)) return;
      if (sbFeeSyncStr && stu.streamId && !sbFeeSyncStr.includes(stu.streamId)) return;
    }

    // Find unique term+year combos where a structure applies to this student
    const termYearSet = new Set();
    feeStructures
      .filter(f => f.classId===clsId
        && (!filterTerm || f.term===filterTerm)
        && (!filterYear || String(f.year)===filterYear))
      .forEach(f => termYearSet.add(f.term + '|' + f.year));

    termYearSet.forEach(key => {
      const [t, y] = key.split('|');
      const exists = feeRecords.some(r => r.studentId===stu.id && r.term===t && String(r.year)===y);
      if (exists) return;

      // Get the right structure for this student (stream-aware)
      const struct = getFeeStructureForStudent(stu, t, y);
      if (!struct) return;

      if (filterStatus && filterStatus !== 'unpaid') return;
      if (search && !stu.name.toLowerCase().includes(search) && !stu.adm.toLowerCase().includes(search)) return;

      const cls = classes.find(c => c.id === clsId);
      const noPrevBal = getPreviousBalance(stu.id, t, y);
      const noCumBal = noPrevBal + struct.totalFee;
      if (filterMinBal > 0 && noCumBal < filterMinBal) return;
      rows.push({ rec: { id: null, studentId: stu.id, classId: clsId, term: t, year: y, totalFee: struct.totalFee, payments: [] }, stu, cls, paid: 0, bal: struct.totalFee, cumBal: noCumBal, pct: 0, statusKey: 'unpaid' });
    });
  });

  rows.sort((a,b) => a.stu.name.localeCompare(b.stu.name));

  // ── Summary: Cleared vs Not Cleared counts ──
  const summaryEl = document.getElementById('fsbSummary');
  if (summaryEl) {
    const clearedCount    = rows.filter(r => r.statusKey === 'cleared').length;
    const partialCount    = rows.filter(r => r.statusKey === 'partial').length;
    const unpaidCount     = rows.filter(r => r.statusKey === 'unpaid').length;
    const notClearedCount = partialCount + unpaidCount;
    summaryEl.innerHTML = `
      <div class="card" style="padding:.6rem 1rem;background:rgba(22,163,74,.08);border:1px solid rgba(22,163,74,.3);border-radius:8px">
        <div style="font-size:.72rem;color:var(--muted)">Cleared</div>
        <div style="font-weight:800;font-size:1.15rem;color:#16a34a"><i class="fa-solid fa-circle-check"></i> ${clearedCount}</div>
      </div>
      <div class="card" style="padding:.6rem 1rem;background:rgba(220,38,38,.08);border:1px solid rgba(220,38,38,.3);border-radius:8px">
        <div style="font-size:.72rem;color:var(--muted)">Not Cleared</div>
        <div style="font-weight:800;font-size:1.15rem;color:#dc2626"><i class="fa-solid fa-circle-xmark"></i> ${notClearedCount}</div>
      </div>
      <div class="card" style="padding:.6rem 1rem;background:rgba(202,138,4,.08);border:1px solid rgba(202,138,4,.3);border-radius:8px">
        <div style="font-size:.72rem;color:var(--muted)">— Partial</div>
        <div style="font-weight:700;font-size:.95rem;color:#ca8a04">${partialCount}</div>
      </div>
      <div class="card" style="padding:.6rem 1rem;background:rgba(220,38,38,.05);border:1px solid rgba(220,38,38,.2);border-radius:8px">
        <div style="font-size:.72rem;color:var(--muted)">— Unpaid</div>
        <div style="font-weight:700;font-size:.95rem;color:#dc2626">${unpaidCount}</div>
      </div>
      <div class="card" style="padding:.6rem 1rem;border-radius:8px">
        <div style="font-size:.72rem;color:var(--muted)">Total</div>
        <div style="font-weight:800;font-size:1.15rem">${rows.length}</div>
      </div>`;
  }

  tbody.innerHTML = rows.length ? rows.map((r, i) => {
    const statusBadge = r.statusKey === 'cleared'
      ? '<span class="badge b-green"><i class="fa-solid fa-circle-check"></i> Cleared</span>'
      : r.statusKey === 'partial'
        ? '<span class="badge b-amber"><i class="fa-solid fa-bolt"></i> Partial</span>'
        : '<span class="badge b-red"><i class="fa-solid fa-circle-xmark"></i> Unpaid</span>';
    return `
      <tr class="${r.statusKey==='unpaid'?'fee-defaulter':r.statusKey==='partial'?'fee-partial':''}">
        <td>${i+1}</td>
        <td>${r.stu.adm}</td>
        <td><strong>${r.stu.name}</strong></td>
        <td>${r.cls?.name || '—'}</td>
        <td>${r.rec.term} ${r.rec.year}</td>
        <td>KES ${parseFloat(r.rec.totalFee||0).toLocaleString()}</td>
        <td style="color:var(--success)">KES ${r.paid.toLocaleString()}</td>
        <td style="color:${r.bal>0?'var(--danger)':'var(--success)'}">KES ${r.bal.toLocaleString()}</td>
        <td style="color:${r.cumBal>0?'var(--danger)':'var(--success)'}" ><strong>KES ${r.cumBal.toLocaleString()}</strong></td>
        <td>${statusBadge}</td>
        <td>
          <button class="btn btn-sm btn-outline" onclick="viewStudentPaymentHistory('${r.stu.id}','${r.rec.term}','${r.rec.year}')"><i class="fa-solid fa-clipboard-list"></i> History</button>
          <button class="btn btn-sm btn-outline" onclick="quickPayStudent('${r.stu.id}','${r.rec.classId}','${r.rec.term}','${r.rec.year}')"><i class="fa-solid fa-credit-card"></i> Pay</button>
          ${(isFullFeesRole || isClassTch) && r.rec.id ? `<button class="btn btn-sm btn-outline" style="color:var(--warning,#d97706);border-color:var(--warning,#d97706)" onclick="editFeeRecord('${r.rec.id}')"><i class="fa-solid fa-pen"></i> Edit</button>` : ''}
          ${isFullFeesRole && r.rec.id ? `<button class="btn btn-sm btn-danger-sm" onclick="deleteFeeRecord('${r.rec.id}')"><i class="fa-solid fa-trash"></i></button>` : ''}
        </td>
      </tr>`;
  }).join('') : '<tr><td colspan="11" style="text-align:center;color:var(--muted);padding:2rem">No fee records found.</td></tr>';
}

function viewStudentPaymentHistory(stuId, term, year) {
  loadFees();
  const stu = students.find(s => s.id === stuId);
  const rec = feeRecords.find(r => r.studentId===stuId && r.term===term && String(r.year)===String(year));
  if (!stu) return;

  const payments = rec ? rec.payments : [];
  const paid = rec ? getRecordTotalPaid(rec) : 0;
  const prevBal = rec ? getPreviousBalance(stuId, term, year) : 0;
  const bal  = rec ? prevBal + getRecordBalance(rec) : 0;

  showModal(`<i class="fa-solid fa-credit-card"></i> ${stu.name} — Payment History (${term} ${year})`, `
    <div style="margin-bottom:1rem">
      <div style="display:flex;gap:1rem;flex-wrap:wrap">
        <div class="fbc-row"><span class="fbc-label">Total Fee</span><span class="fbc-val">KES ${parseFloat(rec?.totalFee||0).toLocaleString()}</span></div>
        <div class="fbc-row"><span class="fbc-label">Paid</span><span class="fbc-val fbc-green">KES ${paid.toLocaleString()}</span></div>
        <div class="fbc-row"><span class="fbc-label">Balance</span><span class="fbc-val fbc-red">KES ${bal.toLocaleString()}</span></div>
      </div>
    </div>
    ${payments.length ? `
      <table style="width:100%;font-size:.82rem;border-collapse:collapse">
        <thead><tr style="background:var(--surface)"><th style="padding:.4rem;text-align:left">Receipt No</th><th>Date</th><th>Amount</th><th>Mode</th><th>Balance After</th><th>Recorded By</th><th></th></tr></thead>
        <tbody>${payments.map(p => `
          <tr style="border-bottom:1px solid var(--border)">
            <td style="padding:.35rem;font-family:monospace;color:var(--primary)">${p.receiptNo}</td>
            <td style="padding:.35rem">${p.date}</td>
            <td style="padding:.35rem;color:var(--success);font-weight:700">KES ${parseFloat(p.amount).toLocaleString()}</td>
            <td style="padding:.35rem">${p.mode}</td>
            <td style="padding:.35rem;color:${p.balanceAfter>0?'var(--danger)':'var(--success)'}">KES ${parseFloat(p.balanceAfter||0).toLocaleString()}</td>
            <td style="padding:.35rem;font-size:.78rem">${p.editedBy ? `<span style="color:var(--primary);font-weight:600">${p.editedBy}</span><br><span style="color:var(--muted);font-size:.7rem">edited ${p.editedAt||''}</span>` : (p.recordedBy ? `<span style="color:var(--primary);font-weight:600">${p.recordedBy}</span>` : '—')}</td>
            <td style="padding:.35rem;display:flex;gap:.3rem;flex-wrap:wrap">
              <button class="btn btn-sm btn-outline" onclick="reprintReceipt('${stuId}','${term}','${year}','${p.id}')" title="Reprint"><i class="fa-solid fa-print"></i></button>
              <button class="btn btn-sm btn-outline" style="color:var(--warning,#d97706);border-color:var(--warning,#d97706)" onclick="closeModal();editPayment('${stuId}','${term}','${year}','${p.id}')" title="Edit"><i class="fa-solid fa-pen"></i></button>
              <button class="btn btn-sm btn-danger-sm" onclick="closeModal();deletePayment('${stuId}','${term}','${year}','${p.id}')" title="Delete"><i class="fa-solid fa-trash"></i></button>
            </td>
          </tr>`).join('')}
        </tbody>
      </table>` : '<p style="color:var(--muted);text-align:center;padding:1rem">No payments recorded yet.</p>'}
  `, [{label:'<i class="fa-solid fa-xmark"></i> Close', cls:'btn-outline', action:'closeModal()'}]);
}

function quickPayStudent(stuId, classId, term, year) {
  closeModal();
  openFeesTab('tabFeePayments', document.getElementById('tbFeePayments'));
  setTimeout(() => {
    const cls = document.getElementById('fpClass');
    if (cls) { cls.value = classId; onFpClassChange(); }
    const yr  = document.getElementById('fpYear');
    if (yr)  yr.value  = year;
    const trm = document.getElementById('fpTerm');
    if (trm) trm.value = term;
    setTimeout(() => {
      const stu = document.getElementById('fpStudent');
      if (stu) { stu.value = stuId; onFpStudentChange(); }
    }, 100);
  }, 150);
}

function reprintReceipt(stuId, term, year, payId) {
  loadFees();
  const rec = feeRecords.find(r => r.studentId===stuId && r.term===term && String(r.year)===String(year));
  if (!rec) return;
  const payment = rec.payments.find(p => p.id === payId);
  if (!payment) return;
  const stu = students.find(s => s.id === stuId);
  const cls = classes.find(c => c.id === rec.classId);
  const prevBal = payment.prevBal !== undefined ? payment.prevBal : getPreviousBalance(stuId, term, year);
  lastReceiptHtml = buildReceiptHTML({ stu, cls, term, year, totalFee: rec.totalFee, payment, prevBal, balBefore: payment.balanceBefore, balAfter: payment.balanceAfter, receiptNo: payment.receiptNo, date: payment.date, mode: payment.mode, notes: payment.notes, amount: payment.amount, schoolName: settings.schoolName || 'School' });
  printLastReceipt();
}

// ═══════════════════════════════════════════
// FEE RECORD EDIT / DELETE
// ═══════════════════════════════════════════

function editFeeRecord(recId) {
  const r = currentUser && currentUser.role;
  if (!(r==='superadmin'||r==='admin'||r==='principal'||r==='bursar')) {
    showToast('Only administrators and the bursar can edit fee records','error'); return;
  }
  loadFees();
  const rec = feeRecords.find(f => f.id === recId);
  if (!rec) { showToast('Fee record not found','error'); return; }
  const stu = students.find(s => s.id === rec.studentId);
  const cls = classes.find(c => c.id === rec.classId);

  showModal(
    `<i class="fa-solid fa-pen"></i> Edit Fee Record — ${stu?.name || 'Unknown'}`,
    `<div style="display:flex;flex-direction:column;gap:1rem;padding:.5rem 0">
      <div style="background:var(--surface,#f8fafc);border-radius:8px;padding:.75rem;font-size:.85rem;color:var(--muted)">
        <strong>${stu?.name || '—'}</strong> &nbsp;|&nbsp; ${cls?.name || '—'} &nbsp;|&nbsp; ${rec.term} ${rec.year}
      </div>
      <div>
        <label style="font-size:.82rem;font-weight:600;display:block;margin-bottom:.35rem">Total Fee (KES)</label>
        <input id="editRecTotalFee" type="number" min="0" step="0.01" value="${parseFloat(rec.totalFee||0)}"
          style="width:100%;padding:.5rem .75rem;border:1px solid var(--border);border-radius:6px;font-size:.95rem">
      </div>
    </div>`,
    [
      { label: '<i class="fa-solid fa-check"></i> Save Changes', cls: 'btn-primary', action: `_saveEditFeeRecord('${recId}')` },
      { label: '<i class="fa-solid fa-xmark"></i> Cancel', cls: 'btn-outline', action: 'closeModal()' }
    ]
  );
}

function _saveEditFeeRecord(recId) {
  loadFees();
  const rec = feeRecords.find(f => f.id === recId);
  if (!rec) { showToast('Fee record not found','error'); return; }
  const newFee = parseFloat(document.getElementById('editRecTotalFee')?.value || 0);
  if (isNaN(newFee) || newFee < 0) { showToast('Enter a valid fee amount','error'); return; }
  rec.totalFee = newFee;
  saveFees();
  closeModal();
  showToast('Fee record updated <i class="fa-solid fa-check"></i>', 'success');
  renderStudentBalances && renderStudentBalances();
}

function deleteFeeRecord(recId) {
  const r = currentUser && currentUser.role;
  if (!(r==='superadmin'||r==='admin'||r==='principal'||r==='bursar')) {
    showToast('Only administrators and the bursar can delete fee records','error'); return;
  }
  loadFees();
  const rec = feeRecords.find(f => f.id === recId);
  if (!rec) { showToast('Fee record not found','error'); return; }
  const stu = students.find(s => s.id === rec.studentId);
  const msg = `Delete all fee data for ${stu?.name || 'this student'} (${rec.term} ${rec.year})? This cannot be undone.`;
  if (!confirm(msg)) return;
  const idx = feeRecords.findIndex(f => f.id === recId);
  if (idx > -1) feeRecords.splice(idx, 1);
  saveFees();
  showToast('Fee record deleted', 'info');
  renderStudentBalances && renderStudentBalances();
}

function editPayment(stuId, term, year, payId) {
  const r = currentUser && currentUser.role;
  if (!(r==='superadmin'||r==='admin'||r==='principal'||r==='bursar')) {
    showToast('Only administrators and the bursar can edit payments','error'); return;
  }
  loadFees();
  const rec = feeRecords.find(f => f.studentId===stuId && f.term===term && String(f.year)===String(year));
  const pay = rec && rec.payments.find(p => p.id === payId);
  if (!pay) { showToast('Payment not found','error'); return; }
  const stu = students.find(s => s.id === stuId);

  showModal(
    `<i class="fa-solid fa-pen"></i> Edit Payment — ${stu?.name || 'Unknown'}`,
    `<div style="display:flex;flex-direction:column;gap:.9rem;padding:.5rem 0">
      <div style="background:var(--surface,#f8fafc);border-radius:8px;padding:.75rem;font-size:.85rem;color:var(--muted)">
        Receipt: <strong style="color:var(--primary)">${pay.receiptNo}</strong> &nbsp;|&nbsp; ${term} ${year}
      </div>
      <div>
        <label style="font-size:.82rem;font-weight:600;display:block;margin-bottom:.35rem">Amount (KES)</label>
        <input id="editPayAmount" type="number" min="0" step="0.01" value="${parseFloat(pay.amount||0)}"
          style="width:100%;padding:.5rem .75rem;border:1px solid var(--border);border-radius:6px;font-size:.95rem">
      </div>
      <div>
        <label style="font-size:.82rem;font-weight:600;display:block;margin-bottom:.35rem">Date</label>
        <input id="editPayDate" type="date" value="${pay.date||''}"
          style="width:100%;padding:.5rem .75rem;border:1px solid var(--border);border-radius:6px;font-size:.95rem">
      </div>
      <div>
        <label style="font-size:.82rem;font-weight:600;display:block;margin-bottom:.35rem">Mode</label>
        <select id="editPayMode" style="width:100%;padding:.5rem .75rem;border:1px solid var(--border);border-radius:6px;font-size:.95rem">
          ${['Cash','M-Pesa','Bank Transfer','Cheque','Card','Other'].map(m => `<option value="${m}"${pay.mode===m?' selected':''}>${m}</option>`).join('')}
        </select>
      </div>
      <div>
        <label style="font-size:.82rem;font-weight:600;display:block;margin-bottom:.35rem">Reference / Notes</label>
        <input id="editPayNotes" type="text" value="${pay.notes||''}" placeholder="Transaction ref, cheque no..."
          style="width:100%;padding:.5rem .75rem;border:1px solid var(--border);border-radius:6px;font-size:.95rem">
      </div>
    </div>`,
    [
      { label: '<i class="fa-solid fa-check"></i> Save Changes', cls: 'btn-primary', action: `_saveEditPayment('${stuId}','${term}','${year}','${payId}')` },
      { label: '<i class="fa-solid fa-xmark"></i> Cancel', cls: 'btn-outline', action: 'closeModal()' }
    ]
  );
}

function _saveEditPayment(stuId, term, year, payId) {
  loadFees();
  const rec = feeRecords.find(f => f.studentId===stuId && f.term===term && String(f.year)===String(year));
  const pay = rec && rec.payments.find(p => p.id === payId);
  if (!pay) { showToast('Payment not found','error'); return; }

  const newAmount = parseFloat(document.getElementById('editPayAmount')?.value || 0);
  if (isNaN(newAmount) || newAmount <= 0) { showToast('Enter a valid amount','error'); return; }

  pay.amount   = newAmount;
  pay.date     = document.getElementById('editPayDate')?.value || pay.date;
  pay.mode     = document.getElementById('editPayMode')?.value || pay.mode;
  pay.notes    = document.getElementById('editPayNotes')?.value || '';
  pay.editedBy = currentUser ? (currentUser.name || currentUser.username) : 'Unknown';
  pay.editedAt = new Date().toLocaleString();

  // Recalculate running balances across all payments for this record
  const prevBal = getPreviousBalance(stuId, term, year);
  let runBal = prevBal + parseFloat(rec.totalFee || 0);
  rec.payments.forEach(p => {
    p.balanceBefore = runBal;
    p.balanceAfter  = runBal - parseFloat(p.amount || 0);
    runBal = p.balanceAfter;
  });

  saveFees();
  closeModal();
  showToast('Payment updated <i class="fa-solid fa-check"></i>', 'success');
  renderStudentBalances && renderStudentBalances();
}

function deletePayment(stuId, term, year, payId) {
  const r = currentUser && currentUser.role;
  if (!(r==='superadmin'||r==='admin'||r==='principal'||r==='bursar')) {
    showToast('Only administrators and the bursar can delete payments','error'); return;
  }
  loadFees();
  const rec = feeRecords.find(f => f.studentId===stuId && f.term===term && String(f.year)===String(year));
  const pay = rec && rec.payments.find(p => p.id === payId);
  if (!pay) { showToast('Payment not found','error'); return; }

  if (!confirm(`Delete payment of KES ${parseFloat(pay.amount).toLocaleString()} (Receipt ${pay.receiptNo})? This cannot be undone.`)) return;

  rec.payments = rec.payments.filter(p => p.id !== payId);

  // Recalculate running balances
  const prevBal = getPreviousBalance(stuId, term, year);
  let runBal = prevBal + parseFloat(rec.totalFee || 0);
  rec.payments.forEach(p => {
    p.balanceBefore = runBal;
    p.balanceAfter  = runBal - parseFloat(p.amount || 0);
    runBal = p.balanceAfter;
  });

  saveFees();
  showToast('Payment deleted', 'info');
  renderStudentBalances && renderStudentBalances();
  // Reopen the history modal to show updated list
  viewStudentPaymentHistory(stuId, term, year);
}

// ═══════════════════════════════════════════
// FEE REMINDERS
// ═══════════════════════════════════════════
function renderFeeReminders() {
  loadFees();
  const filterClass = document.getElementById('fremClass')?.value || '';
  const filterTerm  = document.getElementById('fremTerm')?.value  || '';
  const filterYear  = document.getElementById('fremYear')?.value  || '';

  const isTeacher = currentUser && currentUser.role === 'teacher';
  const isFullFeesRole = currentUser && (currentUser.role==='superadmin'||currentUser.role==='admin'||currentUser.role==='principal'||currentUser.role==='bursar');
  const teacherClassIds = (isTeacher && !isFullFeesRole)
    ? [...new Set(getClassTeacherStreamIds(currentUser.teacherId).map(sid => { const s=streams.find(x=>x.id===sid); return s?s.classId:null; }).filter(Boolean))]
    : null;

  // Find defaulters: students with outstanding balance > 0
  const defaulters = [];
  feeRecords.forEach(rec => {
    if (filterClass && rec.classId !== filterClass) return;
    if (filterTerm  && rec.term !== filterTerm)     return;
    if (filterYear  && String(rec.year) !== filterYear) return;
    if (teacherClassIds && !teacherClassIds.includes(rec.classId)) return;
    const prevBal = getPreviousBalance(rec.studentId, rec.term, rec.year);
    const bal = prevBal + getRecordBalance(rec);
    if (bal <= 0) return;
    const stu = students.find(s => s.id === rec.studentId); if (!stu) return;
    const cls = classes.find(c => c.id === rec.classId);
    defaulters.push({ rec, stu, cls, bal, paid: getRecordTotalPaid(rec) });
  });

  // Also unpaid students with structure
  students.forEach(stu => {
    if (teacherClassIds && !teacherClassIds.includes(stu.classId)) return;
    if (filterClass && stu.classId !== filterClass) return;
    const structs = feeStructures.filter(f => f.classId===stu.classId
      && (!filterTerm || f.term===filterTerm)
      && (!filterYear || String(f.year)===filterYear));
    structs.forEach(struct => {
      const exists = feeRecords.some(r => r.studentId===stu.id && r.term===struct.term && String(r.year)===struct.year);
      if (exists) return;
      const cls = classes.find(c => c.id === stu.classId);
      defaulters.push({ rec: { term: struct.term, year: struct.year, totalFee: struct.totalFee, payments: [] }, stu, cls, bal: struct.totalFee, paid: 0 });
    });
  });

  defaulters.sort((a,b) => b.bal - a.bal);

  const el = document.getElementById('feeRemindersList');
  if (!el) return;

  if (!defaulters.length) {
    el.innerHTML = '<div class="card" style="text-align:center;padding:2.5rem;color:var(--muted)"><i class="fa-solid fa-party-horn"></i> No outstanding fee balances found! All students have cleared their fees.</div>';
    return;
  }

  el.innerHTML = `
    <div class="card" style="margin-bottom:1rem">
      <p style="color:var(--muted);font-size:.85rem">Showing <strong>${defaulters.length}</strong> student(s) with outstanding balances. Click any reminder to print individually.</p>
    </div>
    <div class="fee-reminders-grid">
      ${defaulters.map(d => buildReminderCardHTML(d)).join('')}
    </div>`;
}

function buildReminderCardHTML({ stu, cls, rec, bal, paid }) {
  const schoolName = settings.schoolName || 'The School';
  const term = rec.term, year = rec.year;
  const today = new Date().toLocaleDateString('en-KE', { day:'2-digit', month:'long', year:'numeric' });
  return `
    <div class="reminder-card" onclick="printSingleReminder('${stu.id}','${term}','${year}')">
      <div class="rm-header">
        <div class="rm-badge"><i class="fa-solid fa-triangle-exclamation"></i>️ FEE REMINDER</div>
        <div class="rm-date">${today}</div>
      </div>
      <div class="rm-school">${schoolName}</div>
      <div class="rm-body">
        <p>Dear Parent/Guardian of <strong>${stu.name}</strong>,</p>
        <p>This is a kind reminder that your child's school fees for <strong>${term} ${year}</strong> are outstanding.</p>
        <div class="rm-amounts">
          <div class="rm-amount-row"><span>Class:</span><strong>${cls?.name || '—'}</strong></div>
          <div class="rm-amount-row"><span>Total Fee:</span><strong>KES ${parseFloat(rec.totalFee||0).toLocaleString()}</strong></div>
          <div class="rm-amount-row"><span>Amount Paid:</span><strong style="color:var(--success)">KES ${parseFloat(paid).toLocaleString()}</strong></div>
          <div class="rm-amount-row rm-outstanding"><span>Outstanding Balance:</span><strong style="color:var(--danger)">KES ${parseFloat(bal).toLocaleString()}</strong></div>
        </div>
        <p style="font-size:.78rem;color:var(--muted)">Kindly settle the outstanding amount at your earliest convenience to avoid inconveniences to your child's education. Contact the school for payment arrangements.</p>
      </div>
      <div class="rm-footer">
        <span>Adm: ${stu.adm}</span>
        <button class="btn btn-sm btn-primary" onclick="event.stopPropagation();printSingleReminder('${stu.id}','${term}','${year}')"><i class="fa-solid fa-print"></i> Print</button>
      </div>
    </div>`;
}

function printSingleReminder(stuId, term, year) {
  loadFees();
  const stu = students.find(s => s.id === stuId); if (!stu) return;
  const rec = feeRecords.find(r => r.studentId===stuId && r.term===term && String(r.year)===String(year));
  const struct = rec ? null : feeStructures.find(f => f.classId===stu.classId && f.term===term && String(f.year)===String(year));
  const totalFee = rec ? rec.totalFee : (struct ? struct.totalFee : 0);
  const paid     = rec ? getRecordTotalPaid(rec) : 0;
  const bal      = totalFee - paid;
  const cls      = classes.find(c => c.id === stu.classId);
  const d = { stu, cls, rec: rec||{ term, year, totalFee, payments: [] }, bal, paid };

  const win = window.open('', '_blank', 'width=550,height=700');
  win.document.write(`<!DOCTYPE html><html><head><title>Fee Reminder — ${stu.name}</title><style>
    body{font-family:'Segoe UI',sans-serif;padding:2rem;color:#1e293b;background:#fff;max-width:480px;margin:0 auto}
    .rm-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:.5rem}
    .rm-badge{background:#dc2626;color:#fff;padding:.25rem .75rem;border-radius:20px;font-size:.75rem;font-weight:700}
    .rm-school{font-weight:800;font-size:1.1rem;color:#1a6fb5;margin-bottom:.75rem}
    .rm-amounts{background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:.75rem;margin:.75rem 0}
    .rm-amount-row{display:flex;justify-content:space-between;padding:.2rem 0;font-size:.85rem;border-bottom:1px solid #e2e8f0}
    .rm-amount-row:last-child{border:none} .rm-outstanding{background:#fff1f2;border-radius:4px;padding:.3rem .5rem}
    p{font-size:.85rem;line-height:1.5;margin:.5rem 0}
    .rm-footer{display:flex;justify-content:space-between;margin-top:1rem;padding-top:.75rem;border-top:2px dashed #e2e8f0;font-size:.75rem;color:#94a3b8}
    *{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}
    @page{size:A5 portrait;margin:12mm}
    @media print{button{display:none!important}.rm-badge{background:#dc2626!important;color:#fff!important}.rm-outstanding{background:#fff1f2!important}}
  </style></head><body>
    <div class="rm-header"><div class="rm-badge"><i class="fa-solid fa-triangle-exclamation"></i>️ FEE REMINDER</div><div>${new Date().toLocaleDateString('en-KE',{day:'2-digit',month:'long',year:'numeric'})}</div></div>
    <div class="rm-school">${settings.schoolName || 'School'}</div>
    <p>Dear Parent/Guardian of <strong>${stu.name}</strong>,</p>
    <p>This is a kind reminder that your child's school fees for <strong>${term} ${year}</strong> are outstanding.</p>
    <div class="rm-amounts">
      <div class="rm-amount-row"><span>Class</span><strong>${cls?.name||'—'}</strong></div>
      <div class="rm-amount-row"><span>Admission No.</span><strong>${stu.adm}</strong></div>
      <div class="rm-amount-row"><span>Total Fee</span><strong>KES ${parseFloat(totalFee).toLocaleString()}</strong></div>
      <div class="rm-amount-row"><span>Amount Paid</span><strong style="color:green">KES ${parseFloat(paid).toLocaleString()}</strong></div>
      <div class="rm-amount-row rm-outstanding"><span>Outstanding Balance</span><strong style="color:#dc2626">KES ${parseFloat(bal).toLocaleString()}</strong></div>
    </div>
    <p>Kindly settle the outstanding balance at your earliest convenience. Please visit the school bursar's office or contact us for payment arrangements.</p>
    <p style="font-size:.78rem;color:#64748b">We value your child's education and look forward to your prompt response.</p>
    <div class="rm-footer"><span>Generated: ${new Date().toLocaleString()}</span><span>${settings.schoolName||''}</span></div>
    <button onclick="window.print()" style="margin-top:1rem;padding:.5rem 1.5rem;background:#1a6fb5;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:.85rem"><i class="fa-solid fa-print"></i> Print Reminder</button>
  </body></html>`);
  win.document.close();
  setTimeout(() => { win.focus(); win.print(); }, 300);
}

function printAllReminders() {
  loadFees();
  const filterClass = document.getElementById('fremClass')?.value || '';
  const filterTerm  = document.getElementById('fremTerm')?.value  || '';
  const filterYear  = document.getElementById('fremYear')?.value  || '';
  const isTeacher = currentUser && currentUser.role === 'teacher';
  const isFullFeesRole = currentUser && (currentUser.role==='superadmin'||currentUser.role==='admin'||currentUser.role==='principal'||currentUser.role==='bursar');
  const teacherClassIds = (isTeacher && !isFullFeesRole)
    ? [...new Set(getClassTeacherStreamIds(currentUser.teacherId).map(sid => { const s=streams.find(x=>x.id===sid); return s?s.classId:null; }).filter(Boolean))]
    : null;

  const defaulters = [];
  feeRecords.forEach(rec => {
    if (filterClass && rec.classId !== filterClass) return;
    if (filterTerm  && rec.term !== filterTerm)     return;
    if (filterYear  && String(rec.year) !== filterYear) return;
    if (teacherClassIds && !teacherClassIds.includes(rec.classId)) return;
    const prevBal = getPreviousBalance(rec.studentId, rec.term, rec.year);
    const bal = prevBal + getRecordBalance(rec);
    if (bal <= 0) return;
    const stu = students.find(s => s.id === rec.studentId); if (!stu) return;
    const cls = classes.find(c => c.id === rec.classId);
    defaulters.push({ rec, stu, cls, bal, paid: getRecordTotalPaid(rec) });
  });

  if (!defaulters.length) { showToast('No defaulters to print reminders for', 'info'); return; }

  const reminderBlocks = defaulters.map(d => {
    const { stu, cls, rec, bal, paid } = d;
    return `
      <div style="page-break-inside:avoid;border:1px solid #e2e8f0;border-radius:8px;padding:1.2rem;margin-bottom:1.5rem">
        <div style="display:flex;justify-content:space-between"><span style="background:#dc2626;color:#fff;padding:.2rem .6rem;border-radius:20px;font-size:.72rem;font-weight:700"><i class="fa-solid fa-triangle-exclamation"></i>️ FEE REMINDER</span><span style="font-size:.8rem;color:#64748b">${new Date().toLocaleDateString('en-KE',{day:'2-digit',month:'long',year:'numeric'})}</span></div>
        <div style="font-weight:800;font-size:1rem;color:#1a6fb5;margin:.5rem 0">${settings.schoolName||'School'}</div>
        <p style="font-size:.82rem;margin:.35rem 0">Dear Parent/Guardian of <strong>${stu.name}</strong> (Adm: ${stu.adm}, ${cls?.name||''}),</p>
        <p style="font-size:.82rem;margin:.35rem 0">Your child's fees for <strong>${rec.term} ${rec.year}</strong> are outstanding:</p>
        <div style="background:#f8fafc;border-radius:6px;padding:.5rem .75rem;margin:.5rem 0;font-size:.8rem">
          <div style="display:flex;justify-content:space-between;padding:.15rem 0"><span>Total Fee:</span><strong>KES ${parseFloat(rec.totalFee||0).toLocaleString()}</strong></div>
          <div style="display:flex;justify-content:space-between;padding:.15rem 0"><span>Paid:</span><strong style="color:green">KES ${parseFloat(paid).toLocaleString()}</strong></div>
          <div style="display:flex;justify-content:space-between;padding:.15rem 0;background:#fff1f2;border-radius:4px;padding:.2rem .4rem"><span>Outstanding:</span><strong style="color:#dc2626">KES ${parseFloat(bal).toLocaleString()}</strong></div>
        </div>
        <p style="font-size:.75rem;color:#64748b;margin:.35rem 0">Kindly settle this balance promptly. Contact school administration for assistance.</p>
      </div>`;
  }).join('');

  const win = window.open('', '_blank', 'width=700,height=800');
  win.document.write(`<!DOCTYPE html><html><head><title>Fee Reminders</title><style>body{font-family:'Segoe UI',sans-serif;padding:2rem;color:#1e293b;max-width:600px;margin:0 auto}*{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}@page{size:A4 portrait;margin:12mm}@media print{button{display:none!important}}</style></head><body>
    <div style="text-align:center;margin-bottom:2rem">
      <h2 style="color:#1a6fb5">${settings.schoolName||'School'} — Fee Reminders</h2>
      <p style="color:#64748b;font-size:.85rem">Generated: ${new Date().toLocaleString()} | ${filterTerm||'All Terms'} ${filterYear||''} | ${defaulters.length} students</p>
    </div>
    ${reminderBlocks}
    <button onclick="window.print()" style="padding:.6rem 1.5rem;background:#1a6fb5;color:#fff;border:none;border-radius:6px;cursor:pointer"><i class="fa-solid fa-print"></i> Print All Reminders</button>
  </body></html>`);
  win.document.close();
  setTimeout(() => { win.focus(); win.print(); }, 400);
}

// ═══════════════════════════════════════════
// RECEIPTS LOG
// ═══════════════════════════════════════════
function renderReceiptsLog() {
  loadFees();
  const filterClass = document.getElementById('frctClass')?.value || '';
  const filterTerm  = document.getElementById('frctTerm')?.value  || '';
  const search      = (document.getElementById('frctSearch')?.value || '').toLowerCase();
  const isTeacher = currentUser && currentUser.role === 'teacher';
  const isFullFeesRole = currentUser && (currentUser.role==='superadmin'||currentUser.role==='admin'||currentUser.role==='principal'||currentUser.role==='bursar');
  const teacherClassIds = (isTeacher && !isFullFeesRole)
    ? [...new Set(getClassTeacherStreamIds(currentUser.teacherId).map(sid => { const s=streams.find(x=>x.id===sid); return s?s.classId:null; }).filter(Boolean))]
    : null;

  let allPayments = [];
  feeRecords.forEach(rec => {
    if (filterClass && rec.classId !== filterClass) return;
    if (filterTerm  && rec.term !== filterTerm)     return;
    if (teacherClassIds && !teacherClassIds.includes(rec.classId)) return;
    const stu = students.find(s => s.id === rec.studentId); if (!stu) return;
    const cls = classes.find(c => c.id === rec.classId);
    rec.payments.forEach(p => {
      if (search && !stu.name.toLowerCase().includes(search) && !p.receiptNo.toLowerCase().includes(search) && !stu.adm.toLowerCase().includes(search)) return;
      allPayments.push({ p, rec, stu, cls });
    });
  });

  allPayments.sort((a,b) => new Date(b.p.date) - new Date(a.p.date));

  const tbody = document.getElementById('receiptsLogBody');
  if (!tbody) return;
  tbody.innerHTML = allPayments.length ? allPayments.map(({ p, rec, stu, cls }) => `
    <tr>
      <td style="font-family:monospace;color:var(--primary);font-size:.8rem">${p.receiptNo}</td>
      <td>${p.date}</td>
      <td><strong>${stu.name}</strong><br><span style="font-size:.75rem;color:var(--muted)">${stu.adm}</span></td>
      <td>${cls?.name||'—'}</td>
      <td>${rec.term} ${rec.year}</td>
      <td style="color:var(--success);font-weight:700">KES ${parseFloat(p.amount).toLocaleString()}</td>
      <td>${p.mode}</td>
      <td style="color:${p.balanceAfter>0?'var(--danger)':'var(--success)'}">KES ${parseFloat(p.balanceAfter||0).toLocaleString()}</td>
      <td><button class="btn btn-sm btn-outline" onclick="reprintReceipt('${stu.id}','${rec.term}','${rec.year}','${p.id}')"><i class="fa-solid fa-print"></i> Reprint</button></td>
    </tr>`).join('') : '<tr><td colspan="9" style="text-align:center;color:var(--muted);padding:2rem">No payment receipts found.</td></tr>';
}

// ═══════════════════════════════════════════
// EXPORT FUNCTIONS
// ═══════════════════════════════════════════
function exportFeesSummary() {
  loadFees();
  const filterClass = document.getElementById('fovClass')?.value || '';
  const filterTerm  = document.getElementById('fovTerm')?.value  || '';
  const filterYear  = document.getElementById('fovYear')?.value  || '';

  let rows = [['Student Name','Adm No','Class','Term','Year','Total Fee','Amount Paid','Balance','Status']];
  feeRecords.forEach(rec => {
    if (filterClass && rec.classId !== filterClass) return;
    if (filterTerm  && rec.term !== filterTerm)     return;
    if (filterYear  && String(rec.year) !== filterYear) return;
    const stu = students.find(s => s.id === rec.studentId); if (!stu) return;
    const cls = classes.find(c => c.id === rec.classId);
    const paid = getRecordTotalPaid(rec);
    const prevBal = getPreviousBalance(rec.studentId, rec.term, rec.year);
    const bal  = prevBal + getRecordBalance(rec);
    const status = bal <= 0 ? 'Cleared' : paid > 0 ? 'Partial' : 'Unpaid';
    rows.push([stu.name, stu.adm, cls?.name||'', rec.term, rec.year, rec.totalFee, paid, bal, status]);
  });

  const csv = rows.map(r => r.map(v => `"${String(v||'').replace(/"/g,'""')}"`).join(',')).join('\n');
  const blob = new Blob([csv], { type:'text/csv' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href = url; a.download = `fees_summary_${filterTerm||'all'}_${filterYear||'all'}.csv`;
  a.click(); URL.revokeObjectURL(url);
  showToast('Fee summary exported <i class="fa-solid fa-check"></i>', 'success');
}

function exportStudentBalances() {
  loadFees();
  const filterClass  = document.getElementById('fsbClass')?.value  || '';
  const filterTerm   = document.getElementById('fsbTerm')?.value   || '';
  const filterYear   = document.getElementById('fsbYear')?.value   || '';
  const filterStatus = document.getElementById('fsbStatus')?.value || '';
  const filterMinBal = parseFloat(document.getElementById('fsbMinBalance')?.value || '0') || 0;
  const search       = (document.getElementById('fsbSearch')?.value || '').toLowerCase();

  const isTeacher = currentUser && currentUser.role === 'teacher';
  const isFullFeesRole = currentUser && (currentUser.role==='superadmin'||currentUser.role==='admin'||currentUser.role==='principal'||currentUser.role==='bursar');
  const teacherClassIds = (isTeacher && !isFullFeesRole)
    ? [...new Set(getClassTeacherStreamIds(currentUser.teacherId).map(sid => { const s=streams.find(x=>x.id===sid); return s?s.classId:null; }).filter(Boolean))]
    : null;

  const csvSyncCls = getFeeSyncedClassIds();
  const csvSyncStr = getFeeSyncedStreamIds();

  let rows = [['Student Name','Adm No','Class','Term','Year','Total Fee','Amount Paid','Term Balance','Cumulative Balance','Status']];

  feeRecords.forEach(rec => {
    if (filterTerm   && rec.term !== filterTerm)              return;
    if (filterYear   && String(rec.year) !== filterYear)      return;
    if (filterClass  && rec.classId !== filterClass)          return;
    if (teacherClassIds && !teacherClassIds.includes(rec.classId)) return;
    if (csvSyncCls && !csvSyncCls.includes(rec.classId)) return;
    const stu = students.find(s => s.id === rec.studentId); if (!stu) return;
    if (csvSyncStr && stu.streamId && !csvSyncStr.includes(stu.streamId)) return;
    if (search && !stu.name.toLowerCase().includes(search) && !stu.adm.toLowerCase().includes(search)) return;
    const cls = classes.find(c => c.id === rec.classId);
    const paid = getRecordTotalPaid(rec);
    const prevBal = getPreviousBalance(rec.studentId, rec.term, rec.year);
    const termBal = getRecordBalance(rec);
    const cumBal  = prevBal + termBal;
    const status = Math.round(cumBal * 100) / 100 <= 0 ? 'Cleared' : paid > 0 ? 'Partial' : 'Unpaid';
    if (filterStatus && status.toLowerCase() !== filterStatus) return;
    if (filterMinBal > 0 && cumBal < filterMinBal) return;
    rows.push([stu.name, stu.adm, cls?.name||'', rec.term, rec.year, rec.totalFee, paid, termBal, cumBal, status]);
  });

  // Also no-record unpaid students
  students.forEach(stu => {
    const clsId = stu.classId;
    if (teacherClassIds && !teacherClassIds.includes(clsId)) return;
    if (filterClass && clsId !== filterClass) return;
    if (csvSyncCls && !csvSyncCls.includes(clsId)) return;
    if (csvSyncStr && stu.streamId && !csvSyncStr.includes(stu.streamId)) return;
    if (search && !stu.name.toLowerCase().includes(search) && !stu.adm.toLowerCase().includes(search)) return;
    const structs = feeStructures.filter(f => f.classId===clsId && (!filterTerm||f.term===filterTerm) && (!filterYear||String(f.year)===filterYear));
    structs.forEach(struct => {
      if (feeRecords.some(r => r.studentId===stu.id && r.term===struct.term && String(r.year)===struct.year)) return;
      if (filterStatus && filterStatus !== 'unpaid') return;
      const cls = classes.find(c=>c.id===clsId);
      const noPrevBal = getPreviousBalance(stu.id, struct.term, struct.year);
      const noCumBal  = noPrevBal + parseFloat(struct.totalFee||0);
      if (filterMinBal > 0 && noCumBal < filterMinBal) return;
      rows.push([stu.name, stu.adm, cls?.name||'', struct.term, struct.year, struct.totalFee, 0, struct.totalFee, noCumBal, 'Unpaid']);
    });
  });

  const csv = rows.map(r => r.map(v => `"${String(v||'').replace(/"/g,'""')}"`).join(',')).join('\n');
  const blob = new Blob([csv], { type:'text/csv' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href = url; a.download = `fee_balances_${filterTerm||'all'}_${filterYear||'all'}${filterMinBal>0?'_min'+filterMinBal:''}.csv`;
  a.click(); URL.revokeObjectURL(url);
  showToast('Fee balances exported <i class="fa-solid fa-check"></i>', 'success');
}

// ── Fee PDF Statement ──
function downloadFeeStatementPDF() {
  loadFees();
  const filterClass  = document.getElementById('fsbClass')?.value  || '';
  const filterTerm   = document.getElementById('fsbTerm')?.value   || '';
  const filterYear   = document.getElementById('fsbYear')?.value   || '';
  const filterStatus = document.getElementById('fsbStatus')?.value || '';
  const filterMinBal = parseFloat(document.getElementById('fsbMinBalance')?.value || '0') || 0;
  const search       = (document.getElementById('fsbSearch')?.value || '').toLowerCase();
  const schoolName   = (settings && settings.schoolName) ? settings.schoolName : 'School';

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });

  // Header
  doc.setFillColor(37, 99, 235);
  doc.rect(0, 0, 297, 28, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(16);
  doc.setFont(undefined, 'bold');
  doc.text(schoolName, 14, 11);
  doc.setFontSize(10);
  doc.setFont(undefined, 'normal');
  doc.text('FEE STATEMENT', 14, 18);
  const today = new Date().toLocaleDateString('en-KE', { day:'2-digit', month:'long', year:'numeric' });
  doc.text(`Generated: ${today}`, 14, 24);

  // Filter info
  doc.setTextColor(60, 60, 60);
  doc.setFontSize(8.5);
  let filterText = [];
  if (filterClass) { const cls = classes.find(c=>c.id===filterClass); if(cls) filterText.push(`Class: ${cls.name}`); }
  if (filterTerm)  filterText.push(`Term: ${filterTerm}`);
  if (filterYear)  filterText.push(`Year: ${filterYear}`);
  if (filterStatus) filterText.push(`Status: ${filterStatus.charAt(0).toUpperCase()+filterStatus.slice(1)}`);
  if (filterMinBal > 0) filterText.push(`Min Balance: KES ${filterMinBal.toLocaleString()}+`);
  if (filterText.length) doc.text('Filters: ' + filterText.join('  |  '), 14, 34);

  // Build rows
  let rows = [];
  let totalExpected = 0, totalPaid = 0, totalBal = 0;

  const isTeacher = currentUser && currentUser.role === 'teacher';
  const isFullFeesRole = currentUser && (currentUser.role==='superadmin'||currentUser.role==='admin'||currentUser.role==='principal'||currentUser.role==='bursar');
  const teacherClassIds = (isTeacher && !isFullFeesRole)
    ? [...new Set(getClassTeacherStreamIds(currentUser.teacherId).map(sid => { const s=streams.find(x=>x.id===sid); return s?s.classId:null; }).filter(Boolean))]
    : null;

  feeRecords.forEach(rec => {
    if (filterTerm   && rec.term !== filterTerm)              return;
    if (filterYear   && String(rec.year) !== filterYear)      return;
    if (filterClass  && rec.classId !== filterClass)          return;
    if (teacherClassIds && !teacherClassIds.includes(rec.classId)) return;
    const stu = students.find(s => s.id === rec.studentId); if (!stu) return;
    // Respect fee sync settings (mirrors renderStudentBalances)
    const pdfFeeSyncCls = getFeeSyncedClassIds();
    if (pdfFeeSyncCls && !pdfFeeSyncCls.includes(rec.classId)) return;
    const pdfFeeSyncStr = getFeeSyncedStreamIds();
    if (pdfFeeSyncStr && stu.streamId && !pdfFeeSyncStr.includes(stu.streamId)) return;
    if (search && !stu.name.toLowerCase().includes(search) && !stu.adm.toLowerCase().includes(search)) return;
    const cls   = classes.find(c => c.id === rec.classId);
    const paid  = getRecordTotalPaid(rec);
    const prevBal = getPreviousBalance(rec.studentId, rec.term, rec.year);
    const termBal = getRecordBalance(rec);
    const cumBal  = prevBal + termBal;
    const status = Math.round(cumBal * 100) / 100 <= 0 ? 'Cleared' : paid > 0 ? 'Partial' : 'Unpaid';
    if (filterStatus && status.toLowerCase() !== filterStatus) return;
    if (filterMinBal > 0 && cumBal < filterMinBal) return;
    totalExpected += parseFloat(rec.totalFee||0);
    totalPaid     += paid;
    totalBal      += cumBal;
    rows.push([stu.adm, stu.name, cls?.name||'—', `${rec.term} ${rec.year}`, `KES ${parseFloat(rec.totalFee||0).toLocaleString()}`, `KES ${paid.toLocaleString()}`, `KES ${termBal.toLocaleString()}`, `KES ${cumBal.toLocaleString()}`, status]);
  });

  // Also unpaid rows — with sync + min-balance checks
  const pdfSyncCls2 = getFeeSyncedClassIds();
  const pdfSyncStr2 = getFeeSyncedStreamIds();
  students.forEach(stu => {
    const clsId = stu.classId;
    if (teacherClassIds && !teacherClassIds.includes(clsId)) return;
    if (filterClass && clsId !== filterClass) return;
    // Respect fee sync
    if (pdfSyncCls2 && !pdfSyncCls2.includes(clsId)) return;
    if (pdfSyncStr2 && stu.streamId && !pdfSyncStr2.includes(stu.streamId)) return;
    if (search && !stu.name.toLowerCase().includes(search) && !stu.adm.toLowerCase().includes(search)) return;
    const structs = feeStructures.filter(f => f.classId===clsId && (!filterTerm||f.term===filterTerm) && (!filterYear||String(f.year)===filterYear));
    structs.forEach(struct => {
      if (feeRecords.some(r => r.studentId===stu.id && r.term===struct.term && String(r.year)===struct.year)) return;
      if (filterStatus && filterStatus !== 'unpaid') return;
      const cls = classes.find(c=>c.id===clsId);
      const noPrevBal2 = getPreviousBalance(stu.id, struct.term, struct.year);
      const noCumBal2  = noPrevBal2 + parseFloat(struct.totalFee||0);
      if (filterMinBal > 0 && noCumBal2 < filterMinBal) return;
      totalExpected += parseFloat(struct.totalFee||0);
      totalBal      += parseFloat(struct.totalFee||0);
      rows.push([stu.adm, stu.name, cls?.name||'—', `${struct.term} ${struct.year}`, `KES ${parseFloat(struct.totalFee||0).toLocaleString()}`, 'KES 0', `KES ${parseFloat(struct.totalFee||0).toLocaleString()}`, `KES ${noCumBal2.toLocaleString()}`, 'Unpaid']);
    });
  });

  rows.sort((a,b) => a[1].localeCompare(b[1]));

  // Cleared vs Not Cleared counts (status is the last column of each row)
  let clearedCount = 0, notClearedCount = 0;
  rows.forEach(r => {
    if (r[r.length - 1] === 'Cleared') clearedCount++;
    else notClearedCount++;
  });

  const startY = filterText.length ? 38 : 32;

  doc.autoTable({
    startY,
    head: [['Adm No', 'Student Name', 'Class', 'Term/Year', 'Total Fee', 'Paid', 'Balance', 'Cumulative', 'Status']],
    body: rows,
    theme: 'grid',
    headStyles: { fillColor: [37, 99, 235], textColor: 255, fontStyle: 'bold', fontSize: 8 },
    bodyStyles: { fontSize: 7.5, cellPadding: 1.5 },
    columnStyles: { 1: { cellWidth: 32 }, 6: { halign: 'right' }, 7: { halign: 'right', fontStyle: 'bold' }, 8: { fontStyle: 'bold' } },
    didParseCell: (data) => {
      if (data.section === 'body' && data.column.index === 8) {
        const val = data.cell.raw;
        if (val === 'Cleared') data.cell.styles.textColor = [22, 163, 74];
        else if (val === 'Partial') data.cell.styles.textColor = [202, 138, 4];
        else data.cell.styles.textColor = [220, 38, 38];
      }
    },
    margin: { left: 14, right: 14 }
  });

  // Summary footer
  const finalY = doc.lastAutoTable.finalY + 6;
  doc.setFillColor(245, 247, 250);
  doc.rect(14, finalY, 269, 25, 'F');
  doc.setFontSize(8.5);
  doc.setFont(undefined, 'bold');
  doc.setTextColor(30, 30, 30);
  doc.text(`Total Students: ${rows.length}`, 18, finalY + 5.5);
  doc.setTextColor(22, 163, 74);
  doc.text(`Cleared: ${clearedCount}`, 90, finalY + 5.5);
  doc.setTextColor(220, 38, 38);
  doc.text(`Not Cleared: ${notClearedCount}`, 150, finalY + 5.5);
  doc.setTextColor(37, 99, 235);
  doc.text(`Expected: KES ${totalExpected.toLocaleString()}`, 18, finalY + 12.5);
  doc.setTextColor(22, 163, 74);
  doc.text(`Collected: KES ${totalPaid.toLocaleString()}`, 90, finalY + 12.5);
  doc.setTextColor(220, 38, 38);
  doc.text(`Cumulative: KES ${totalBal.toLocaleString()}`, 150, finalY + 12.5);

  const label = [filterClass&&classes.find(c=>c.id===filterClass)?.name, filterTerm, filterYear].filter(Boolean).join('_') || 'all';
  doc.save(`fee_statement_${label}.pdf`);
  showToast('Fee statement PDF downloaded <i class="fa-solid fa-check"></i>', 'success');
}

// ── Fee Excel Import ──
function handleFeeImport(input) {
  const file = input.files[0]; if (!file) return;
  const reader = new FileReader();
  reader.onload = e => {
    try {
      const wb   = XLSX.read(e.target.result, { type: 'array' });
      const ws   = wb.Sheets[wb.SheetNames[0]];
      const data = XLSX.utils.sheet_to_json(ws);
      loadFees();
      let added = 0, updated = 0, skipped = 0;
      data.forEach(row => {
        const admNo  = String(row['AdmNo']  || row['admno']  || row['Adm No'] || '').trim();
        const term   = String(row['Term']   || row['term']   || '').trim();
        const year   = String(row['Year']   || row['year']   || '').trim();
        const total  = parseFloat(row['TotalFee']    || row['total_fee']    || 0);
        const amount = parseFloat(row['AmountPaid']  || row['amount_paid']  || 0);
        const mode   = String(row['PaymentMode'] || row['payment_mode'] || 'Cash').trim();
        const notes  = String(row['Notes']  || row['notes']  || '').trim();
        const rno    = String(row['ReceiptNo'] || row['receipt_no'] || genReceiptNo()).trim();
        let   pdate  = String(row['PaymentDate'] || row['payment_date'] || '').trim();
        if (!pdate) pdate = new Date().toISOString().slice(0,10);

        // PrevTermBalance: if provided in Excel, use it; otherwise auto-calculate from records
        const prevBalRaw = row['PrevTermBalance'] ?? row['prev_term_balance'] ?? row['Prev Term Balance'];
        const hasPrevBal = prevBalRaw !== undefined && prevBalRaw !== '' && !isNaN(parseFloat(prevBalRaw));

        if (!admNo || !term || !year || !total) { skipped++; return; }
        const stu = students.find(s => s.adm === admNo);
        if (!stu) { skipped++; return; }

        let rec = feeRecords.find(r => r.studentId===stu.id && r.term===term && String(r.year)===year);
        if (!rec) {
          rec = { id: uid(), studentId: stu.id, classId: stu.classId, term, year, totalFee: total, payments: [] };
          feeRecords.push(rec);
          added++;
        } else {
          if (total) rec.totalFee = total;
          updated++;
        }

        if (amount > 0) {
          // Use Excel-supplied previous balance if present, else auto-calculate
          const prevBal   = hasPrevBal ? parseFloat(prevBalRaw) : getPreviousBalance(rec.studentId, rec.term, rec.year);
          const balBefore = prevBal + getRecordBalance(rec);  // prev balance + this term's remaining
          const balAfter  = balBefore - amount;               // cumulative balance after this payment
          rec.payments.push({ id: uid(), receiptNo: rno, date: pdate, amount, mode, notes, balanceBefore: balBefore, balanceAfter: balAfter });
        }
      });
      saveFees();
      renderStudentBalances && renderStudentBalances();
      renderFeeOverview    && renderFeeOverview();
      showToast(`${added} new records, ${updated} updated, ${skipped} skipped <i class="fa-solid fa-check"></i>`, 'success');
    } catch(err) { showToast('Error reading file', 'error'); console.error(err); }
  };
  reader.readAsArrayBuffer(file); input.value = '';
}

function downloadFeeImportTemplate() {
  // Column headers
  const headers = [
    'AdmNo', 'Term', 'Year', 'TotalFee', 'PrevTermBalance',
    'AmountPaid', 'CumulativeBalance', 'PaymentDate', 'PaymentMode', 'ReceiptNo', 'Notes'
  ];
  // Example data rows — CumulativeBalance column left null; formula added below
  const row1 = ['ADM001', 'Term 1', '2025', 12000, 500,  6000, null, '2025-01-15', 'Mpesa', 'RCP001', 'First instalment'];
  const row2 = ['ADM002', 'Term 1', '2025', 12000, 0,   12000, null, '2025-01-15', 'Cash',  'RCP002', 'Full payment'];

  const ws = XLSX.utils.aoa_to_sheet([headers, row1, row2]);

  // CumulativeBalance = PrevTermBalance(E) + TotalFee(D) - AmountPaid(F)
  ws['G2'] = { t: 'n', f: '=E2+D2-F2' };
  ws['G3'] = { t: 'n', f: '=E3+D3-F3' };

  ws['!cols'] = [
    { wch: 10 }, { wch: 10 }, { wch: 8  }, { wch: 12 }, { wch: 18 },
    { wch: 12 }, { wch: 20 }, { wch: 14 }, { wch: 14 }, { wch: 12 }, { wch: 22 }
  ];

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'FeePayments');

  // Instructions sheet
  const notesAoa = [
    ['Column',           'Description',                                                                                 'Required'],
    ['AdmNo',            'Student admission number — must match exactly',                                               'Yes'     ],
    ['Term',             'Term name: Term 1 / Term 2 / Term 3',                                                        'Yes'     ],
    ['Year',             '4-digit year e.g. 2025',                                                                     'Yes'     ],
    ['TotalFee',         "This term's total fee amount (KES)",                                                         'Yes'     ],
    ['PrevTermBalance',  'Outstanding balance carried forward from previous term (KES). Enter 0 if none. If blank, the system auto-calculates from existing records.', 'No'],
    ['AmountPaid',       'Amount being paid this import (KES). Leave 0 to register fee without recording a payment.', 'No'      ],
    ['CumulativeBalance','AUTO-CALCULATED: PrevTermBalance + TotalFee − AmountPaid. For reference only — do not edit.','Auto'    ],
    ['PaymentDate',      'Date of payment (YYYY-MM-DD). Defaults to today if blank.',                                  'No'      ],
    ['PaymentMode',      'Cash / Mpesa / Bank / Cheque',                                                               'No'      ],
    ['ReceiptNo',        'Receipt number. Auto-generated if blank.',                                                    'No'      ],
    ['Notes',            'Any notes about the payment.',                                                                'No'      ],
  ];
  const wsNotes = XLSX.utils.aoa_to_sheet(notesAoa);
  wsNotes['!cols'] = [{ wch: 20 }, { wch: 72 }, { wch: 10 }];
  XLSX.utils.book_append_sheet(wb, wsNotes, 'Instructions');

  XLSX.writeFile(wb, 'fee_payments_template.xlsx');
}


function printFeeOverview() {
  loadFees();
  const filterClass = document.getElementById('fovClass')?.value || '';
  const filterTerm  = document.getElementById('fovTerm')?.value  || '';
  const filterYear  = document.getElementById('fovYear')?.value  || '';
  const visibleClasses = filterClass ? classes.filter(c=>c.id===filterClass) : classes;

  let totalExp=0, totalCol=0, totalOut=0;
  const tableRows = visibleClasses.map(cls => {
    const classStudents = students.filter(s => s.classId === cls.id);
    let expected=0, collected=0;
    classStudents.forEach(stu => {
      const recs = feeRecords.filter(r => r.studentId===stu.id && (!filterTerm||r.term===filterTerm) && (!filterYear||String(r.year)===filterYear));
      recs.forEach(r => { expected += parseFloat(r.totalFee||0); collected += getRecordTotalPaid(r); });
    });
    const out = expected - collected;
    const pct = expected > 0 ? Math.round(collected/expected*100) : 0;
    totalExp += expected; totalCol += collected; totalOut += out;
    return `<tr><td>${cls.name}</td><td>${classStudents.length}</td><td>KES ${expected.toLocaleString()}</td><td>KES ${collected.toLocaleString()}</td><td style="color:${out>0?'#dc2626':'#16a34a'}">KES ${out.toLocaleString()}</td><td>${pct}%</td></tr>`;
  }).join('');

  const win = window.open('', '_blank', 'width=800,height=600');
  win.document.write(`<!DOCTYPE html><html><head><title>Fee Report</title><style>
    body{font-family:'Segoe UI',sans-serif;padding:2rem;color:#1e293b}
    h2{color:#1a6fb5} table{width:100%;border-collapse:collapse;margin-top:1rem;font-size:.88rem}
    th{background:#1a6fb5;color:#fff;padding:.5rem;text-align:left}
    td{padding:.45rem;border-bottom:1px solid #e2e8f0}
    tfoot td{font-weight:700;background:#f8fafc;border-top:2px solid #1a6fb5}
    *{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}
    @page{size:A5 portrait;margin:12mm}
    @media print{button{display:none!important}.rm-badge{background:#dc2626!important;color:#fff!important}.rm-outstanding{background:#fff1f2!important}}
  </style></head><body>
    <h2>${settings.schoolName||'School'} — Fee Collection Report</h2>
    <p style="color:#64748b;font-size:.85rem">${filterTerm||'All Terms'} ${filterYear||''} | Generated: ${new Date().toLocaleString()}</p>
    <table>
      <thead><tr><th>Class</th><th>Students</th><th>Expected</th><th>Collected</th><th>Outstanding</th><th>Rate</th></tr></thead>
      <tbody>${tableRows}</tbody>
      <tfoot><tr><td>TOTALS</td><td>${students.length}</td><td>KES ${totalExp.toLocaleString()}</td><td>KES ${totalCol.toLocaleString()}</td><td style="color:${totalOut>0?'#dc2626':'#16a34a'}">KES ${totalOut.toLocaleString()}</td><td>${totalExp>0?Math.round(totalCol/totalExp*100):0}%</td></tr></tfoot>
    </table>
    <button onclick="window.print()" style="margin-top:1rem;padding:.5rem 1.2rem;background:#1a6fb5;color:#fff;border:none;border-radius:6px;cursor:pointer"><i class="fa-solid fa-print"></i> Print</button>
  </body></html>`);
  win.document.close();
  setTimeout(() => { win.focus(); }, 300);
}

